const e=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"کەرەستەکانی خۆپاراستن (PPE)",subtitle:"Personal Protective Equipment",summary:"ناسینی کەرەستەکانی خۆپاراستن و بەکارهێنانی دروستیان",blocks:[{body:"کەرەستەکانی خۆپاراستنی کەسی (PPE) دوایین هێڵی بەرگرین دژی برینداربوون: پێش ئەوان، دەبێت مەترسی بە ڕێگا ئەندازیارییەکان و ڕێکارەکانی کار لاببرێت یان کەم بکرێتەوە (Hierarchy of Controls). لە کارگەکاندا بەکارهێنانی PPE ئارەزوومەندانە نییە، بەڵکو ناچارییە."},{heading:"١. جۆرە سەرەکییەکانی PPE",body:"بۆ هەر ئەندامێکی لەش کەرەستەیەکی تایبەت هەیە:",points:["سەر: کڵاوی پاراستن (Hard Hat) — پاراستن دژی کەوتنی شتەکان و لێدان.","چاو: چاویلکەی سەلامەتی (Safety Glasses) — پاراستن دژی تۆز، ماددە کیمیاییەکان و پڕیشک.","گوێ: پارێزەری گوێ (Earmuffs / Earplugs) — دژی دەنگی بەرزی ئامێرەکان (٨٥ dB(A) و زیاتر).","دەست: دەستکێش — دژی بڕین، گەرما و ماددە کیمیاییەکان.","پێ: پێڵاوی سەلامەتی بە سەری ئاسنین (Steel Toe) — دژی پلیشانەوە و کەوتنی شتی قورس.","لەش: جلی ئاشکرا (Hi-Vis) بە ڕەنگی گەش — بۆ ئەوەی شۆفێران و کرێکارانی تر بتبینن."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"PPE",description:"ڕێگای دروستی لەبەرکردن"}],quiz:[{question:"بەپێی ستانداردە ئەوروپییەکان، کەی بەکارهێنانی پارێزەری گوێ ناچاری دەبێت؟",options:[{text:"٥٠ dB",correct:!1},{text:"٧٠ dB",correct:!1},{text:"٨٥ dB(A) و زیاتر (تێکڕای ٨ کاتژمێری کار)",correct:!0},{text:"١٢٠ dB",correct:!1}],explanation:"بەپێی ڕێنماییی ئەوروپی 2003/10/EC، کاتێک تێکڕای دەنگ لە ٨ کاتژمێری کاردا دەگاتە ٨٥ dB(A)، دەبێت پارێزەری گوێ بەکاربهێنرێت. OSHA یش لە ٨٥ dBA داوای بەرنامەی پاراستنی بیستن دەکات."}]},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"سەلامەتیی ئامێرەکان",subtitle:"Machine Safety & Guarding",summary:"پاراستنی کرێکاران لە بەشە جووڵاوەکانی ئامێرەکان",blocks:[{body:"ئامێرە پیشەسازییەکان هێزێکی زۆریان هەیە و دەتوانن لە چرکەیەکدا برینی سەخت یان لەدەستدانی ئەندامێکی لەش دروست بکەن."},{heading:"١. پارێزەرەکانی ئامێر (Machine Guards)",body:"دەبێت ئەم پاراستنانە لەسەر هەموو ئامێرە مەترسیدارەکان هەبن:",points:["پارێزەری جێگیر: بۆ داپۆشینی قایش و چەرخە دەندانەدارە جووڵاوەکان.","دوگمەی وەستاندنی تەنگانە (E-Stop): دەبێت نزیکی دەستی کرێکار بێت و بە ڕەنگی سوور لەسەر بنکەیەکی زەرد بێت.","هەستەوەرەکانی وەستاندن: ئامێرەکە دەوەستێت ئەگەر دەست یان لەش لە شوێنی مەترسیدار نزیک ببێتەوە."]},{heading:"٢. یاسا زێڕینەکان",body:"پێش کار و لە کاتی کاردا:",points:["هەرگیز پارێزەری ئامێر لامەبە کاتێک ئامێرەکە کار دەکات.","جلی شل، زنجیر و ئەنگوستیلە لەبەر مەکە و قژی درێژ ببەستەوە، بۆ ئەوەی نەکەونە ناو ئامێرەکەوە.","ئەگەر ئامێرەکە تێکچوو، یەکسەر بە دوگمەی E-Stop بیوەستێنە و بەبێ ڕێکاری LOTO دەستت مەخە ناو ئامێرەکەوە."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"پارێزەرەکانی ئامێر",description:"نموونەی پارێزەرێکی دروست"}],quiz:[{question:"ئایا دروستە پارێزەری ئامێر لاببرێت کاتێک ئامێرەکە کار دەکات؟",options:[{text:"بەڵێ، ئەگەر پێویست بوو",correct:!1},{text:"نەخێر، بە هیچ شێوەیەک دروست نییە",correct:!0},{text:"تەنها بۆ پاککردنەوە",correct:!1},{text:"هەموو وەڵامەکان دروستن",correct:!1}],explanation:"لابردنی پارێزەری ئامێر لە کاتی کارکردنیدا یەکێکە لە مەترسیدارترین ڕەفتارەکان. پاککردنەوە و چاککردنەوە تەنها دوای وەستاندن و قوفڵکردنی ئامێرەکە (LOTO) ئەنجام دەدرێن."}]},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"سەلامەتیی کارەبا",subtitle:"Industrial Electrical Safety (LOTO)",summary:"مەترسییەکانی کارەبا و سیستەمی قوفڵکردن و نیشانەکردن (LOTO)",blocks:[{body:"کارەبا لە کارگەکاندا بە ڤۆڵتیەی بەرز کار دەکات؛ کارەبالێدان دەتوانێت ببێتە هۆی مردن یان سووتانی سەخت."},{heading:"١. سیستەمی قوفڵکردن و نیشانەکردن (Lockout/Tagout — LOTO)",body:"ئەمە گرنگترین ڕێکارە پێش چاککردنەوە یان پاککردنەوەی ئامێرەکان:",points:["قوفڵکردن (Lockout): سەرچاوەی سەرەکیی کارەبا ببڕە و قوفڵێکی کەسیی لێ بدە.",'نیشانەکردن (Tagout): کارتێکی پێوە هەڵبواسە کە لەسەری نووسرابێت: "کاری لەسەر دەکرێت — هەڵیمەکە"، لەگەڵ ناوی خۆت و بەروار.',"کلیلەکە تەنها لە دەستی ئەو کەسەدا بێت کە چاککردنەوەکە دەکات؛ و پێش دەستپێکردن دڵنیا ببەوە کە ئامێرەکە بەڕاستی بێ وزەیە (Verify)."]},{heading:"٢. پشکنینی کێبڵەکان",body:"هەمیشە بپشکنە:",points:["کێبڵی بڕاو یان ئەو کێبڵانەی وایەرەکانیان دیارە بەکارمەهێنە.","کارەبا و ئاو دوژمنی یەکترن؛ لە شوێنی تەڕدا ئامێری کارەبایی بەکارمەهێنە."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"LOTO",description:"چۆن قوفڵ بەکاردەهێنین؟"}],quiz:[{question:"مەبەست لە LOTO چییە؟",options:[{text:"پاککردنەوە",correct:!1},{text:"بڕین و قوفڵکردنی وزە پێش چاککردنەوە",correct:!0},{text:"زیادکردنی خێرایی ئامێرەکە",correct:!1},{text:"هیچ کامیان نییە",correct:!1}],explanation:"سیستەمی LOTO بەکاردەهێنرێت بۆ ئەوەی کەس کارەبا هەڵنەکاتەوە کاتێک کرێکار لەسەر ئامێرەکە کار دەکات (OSHA 29 CFR 1910.147)."}]},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"ئاگرکوژێنەرەوە — ڕاهێنانی تەواو",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینی جۆرەکانی ئاگرکوژێنەرەوە، پۆلەکانی ئاگر و ڕێکاری PASS بە وردی",blocks:[{body:"ئاگرکوژێنەرەوە (Fire Extinguisher) ئامێرێکی سەرەکییە بۆ کوژاندنەوەی ئاگری بچووک لە قۆناغی سەرەتاییدا. لە کارگەکاندا هەر کارمەندێک دەبێت بزانێت چۆن بە خێرایی و بە دروستی ئاگرکوژێنەرەوە بەکاربهێنێت. زانینی جۆرەکانی ئاگرکوژێنەرەوە و پۆلەکانی ئاگر ژیانی خۆت و هاوڕێکانت دەپارێزێت. ئاگرکوژێنەرەوەی دەستی تەنها چەند چرکەیەک کار دەکات، بۆیە دەبێت بە دروستی ئاراستە بکرێت. ئەگەر ئاگرەکە گەورە بوو یان دووکەڵ زۆر بوو، ئاگرکوژێنەرەوەکە جێبهێڵە، دەربچۆ و پەیوەندی بە ١١٥ بکە."},{heading:"١. پۆلەکانی ئاگر بەپێی NFPA (Fire Classes)",body:"بەپێی سیستەمی ئەمریکی (NFPA)، ئاگر دابەش دەبێت بۆ ٥ پۆل و هەر پۆلێک پێویستی بە ئاگرکوژێنەرەوەیەکی گونجاو هەیە. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F.",points:["پۆلی A (کەرەستەی ڕەق): دار، کاغەز، قوماش، پلاستیک. ئاگرکوژێنەرەوە: ئاو، کەف، تۆزی ABC.","پۆلی B (شلەمەنی و گازە ئاگرگرەکان): بەنزین، نەوت، ڕۆن، ئەلکهول، گاز. شلەمەنی: CO₂، تۆزی ABC یان کەف؛ بۆ ئەلکهول و شلە جەمسەرییەکانی تر (polar solvents): CO₂، تۆزی وشک یان کەفی بەرگەگری ئەلکهول (AR foam)، چونکە کەفی ئاسایی لەسەریان تێکدەچێت. گاز: یەکەمجار گازەکە ڕابگرە ئەگەر سەلامەت بوو؛ هەرگیز ئاگری گاز مەکوژێنەرەوە ئەگەر نەتوانیت گازەکە ڕابگریت. (هەرگیز ئاو بەکارمەهێنە!)","پۆلی C (ئەو ئامێرە کارەباییانەی کارەبایان تێدایە): سویچ، ترانسفۆرمەر، تابلۆ، مۆلیدە (جەنەڕەیتەر). ئاگرکوژێنەرەوە: CO₂، تۆزی ABC، Clean Agent. (ئاو و کەف بەکارمەهێنە مەگەر لەیبڵەکە پۆلی C یان نیشانەی تاقیکردنەوەی کارەبایی نیشان بدات، وەک هەندێک ئاگرکوژێنەرەوەی تەمی ئاو (water mist)!)","پۆلی D (کانزاکان): کانزا ئاگرگرەکان — مەگنیسیۆم، تیتانیۆم، سۆدیۆم و تۆزی ئەلەمنیۆم. ئاگرکوژێنەرەوە: تەنها ئاگرکوژێنەرەوەیەکی پۆلی D یان ماددەیەک کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت؛ ماددەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە. (ئاو دەتوانێت تەقینەوە دروست بکات!)","پۆلی K (چێشتخانە): ڕۆن و چەورییەکانی چێشتلێنان. ئاگرکوژێنەرەوە: Wet Chemical. (ئاو ڕۆنی داغ بڵاو دەکاتەوە!) — لە EN 2 دا ئەمە پۆلی F ە."]},{heading:"٢. جۆرەکانی ئاگرکوژێنەرەوە لە کارگەکاندا",body:"ڕەنگ پۆلی ئاگر نییە. بەپێی BS EN 3، لەشی ئاگرکوژێنەرەوە سوورە؛ لە بەریتانیا پارچەیەکی ڕەنگکراو (BS 7863) ماددەکە نیشان دەدات. وڵاتانی تر ڕەنگی تر بەکاردەهێنن و ڕەنگەکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە، بۆیە هەمیشە لەیبڵ و نیشانەکانی پۆل بخوێنەرەوە. پۆلەکانی خوارەوە بە پیتەکانی NFPA ن:",points:["ئاگرکوژێنەرەوەی ئاو (Water): هەمووی سوور، بێ پارچەی ڕەنگکراو — تەنها بۆ پۆلی A (دار، کاغەز). هەرگیز بۆ کارەبا یان ڕۆن بەکاری مەهێنە!","ئاگرکوژێنەرەوەی CO₂: پارچەی ڕەش لە بەریتانیا — بۆ پۆلی B و ئامێرە کارەباییەکان کە کارەبایان تێدایە (B و C بەپێی NFPA؛ بەپێی EN 2، C گازە و CO₂ بۆ ئاگری گاز نییە). گازێکی زۆر سارد دەردەچێت و لوولەکە (Horn) زۆر سارد دەبێت؛ تەنها دەسکەکە بگرە و هەرگیز دەست بە لوولەکەوە مەگرە، دەستت بە سەرما دەسووتێت! مەودای CO₂ کورتە و بۆ ئاگری قووڵی دار و کاغەز نییە: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵەکەی هاتووە و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە. لە ژووری بچووکدا دوای بەکارهێنان دەربچۆ و هەوا بگۆڕە، چونکە CO₂ ئۆکسجین کەم دەکاتەوە.","ئاگرکوژێنەرەوەی تۆزی ABC (Dry Powder): پارچەی شین لە بەریتانیا — بۆ پۆلەکانی A، B و C (نەک بۆ D و K). بڵاوترین جۆرە. تۆزێکی سپی دەردەچێت؛ کەموکووڕییەکەی: بینین کەم دەکاتەوە و ئامێرەکان پیس دەکات.","ئاگرکوژێنەرەوەی کەف (Foam/AFFF): پارچەی کرێمی لە بەریتانیا — بۆ پۆلەکانی A و B. کەفەکە لەسەر شلەمەنییەکە ڕادەخات و ئۆکسجینی لێ دەبڕێت. بۆ کارەبا بەکاری مەهێنە!","ئاگرکوژێنەرەوەی Clean Agent: پۆلەکانی بەپێی مۆدێل جیاوازن، بۆیە لەیبڵەکە بخوێنەرەوە (زۆرجار B و C بە پیتەکانی NFPA؛ هەندێک مۆدێل بۆ A یش) — بۆ ئامێرە هەستیارەکان و ژووری سێرڤەرەکان. پاشماوە بەجێناهێڵێت و زیان بە ئامێرە ئەلیکترۆنییەکان ناگەیەنێت.","ئاگرکوژێنەرەوەی تایبەت (Class D): بۆ کانزا ئاگرگرەکان لە کارگەکاندا — دەبێت ناوی ئەو کانزایەی لەوێ بەکاردێت لەسەر لەیبڵەکەی هاتبێت. هەرگیز ئاو مەکە سەر کانزای ئاگرگرتوو!"]},{heading:"٣. ڕێکاری PASS — بە وردی",body:"پێش بەکارهێنانی ئاگرکوژێنەرەوە، دەبێت هەموو وەڵامەکان «بەڵێ» بن: ئاگرەکە بچووک و تازە دەستی پێکردبێت، ئاگرکوژێنەرەوەکە گونجاو بێت، ڕێگای دەرچوون لە پشتتەوە بێت، ئاگادارکردنەوە درابێت و پەیوەندی بە ١١٥ەوە کرابێت، تۆ ڕاهێنراو بیت، و هیچ دووکەڵ یان گەرمایەک ڕێگات نەگرێت. ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، دەربچۆ و دەرگاکە دابخە. PASS ڕێکاری گشتییە بۆ زۆربەی ئاگرکوژێنەرەوە دەستییەکان؛ ئاگرکوژێنەرەوەکانی Class D، Wet Chemical، Clean Agent و ئەوانەی لەسەر تایەن: بەپێی لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر بەکاریان بهێنە:",points:["P = Pull (دەریبکێشە): سنجاقی سەلامەتی (Safety Pin) دەربکێشە. ئەم سنجاقە ڕێگە نادات ئاگرکوژێنەرەوەکە بە هەڵە کار بکات.","A = Aim (ئاراستەی بکە): لوولەی ئاگرکوژێنەرەوەکە ئاراستەی بنکەی ئاگرەکە بکە — نەک سەری بڵێسەکە! سووتەمەنیی ئاگرەکە لە بنەوەیە.","S = Squeeze (بیگوشە): دەسکەکانی ئاگرکوژێنەرەوەکە بە هێز بگوشە بۆ ئەوەی ماددەکە دەربچێت.","S = Sweep (بیجووڵێنە): لوولەکە بە چەپ و ڕاستدا لەسەر بنکەی ئاگرەکە بجووڵێنە تا ئاگرەکە بە تەواوی دەکوژێتەوە؛ پاشان چاودێریی شوێنەکە بکە بۆ ئەوەی ئاگرەکە دووبارە هەڵنەگیرسێتەوە."]},{heading:"٤. پشکنینی مانگانەی ئاگرکوژێنەرەوەکان",body:"پشکنینی چاوی هەموو مانگێک، لەلایەن کەسی بەرپرسەوە (NFPA 10):",points:["پەستانی ناو ئاگرکوژێنەرەوەکە (Pressure Gauge)، ئەگەر هەبێت: دەبێت دەرزییەکە لە ناوچەی سەوزدا بێت. ئاگرکوژێنەرەوەی CO₂ پەستانپێوی نییە: هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە.","سنجاقی سەلامەتی و مۆرەکەی: دەبێت لە شوێنی خۆیاندا بن و نەشکێنرابن.","لوولە (Nozzle): نابێت شکاو یان گیراو بێت.","لەشی ئاگرکوژێنەرەوەکە: نابێت ژەنگاوی، درزدار یان زیانلێکەوتوو بێت.","کارتی پشکنین و لەیبڵ: دەبێت بەرواری دوایین پشکنین لەسەر کارتەکە بێت؛ لەیبڵەکە بخوێنرێتەوە و ڕووی لە دەرەوە بێت؛ ئاگرکوژێنەرەوەکە لە شوێنی خۆیدا بێت، دیار بێت و بە ئاسانی بگاتێ.","تێبینی: ئەمانە لێک جیا بکەرەوە. پشکنین و چاکسازیی ساڵانە لەلایەن کەسێکی شارەزاوە؛ پڕکردنەوە (Recharge) دوای هەر بەکارهێنانێک، تەنانەت ئەگەر کورتیش بێت؛ چاکسازیی ٦ ساڵە: ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو (stored-pressure) کە پێویستیان بە تاقیکردنەوەی هایدرۆستاتیکیی ١٢ ساڵە هەیە، هەر ٦ ساڵ جارێک بەتاڵ دەکرێنەوە و ناوەوەیان دەپشکنرێت؛ تاقیکردنەوەی هایدرۆستاتیکی (Hydrostatic Test، تاقیکردنەوەی پەستانی لەشەکەی) هەر ٥ ساڵ بۆ ئاگرکوژێنەرەوەکانی ئاو، کەف (AFFF)، CO₂ و تۆزی وشکی ستێنلێس ستیل (stainless steel)، و هەر ١٢ ساڵ بۆ ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو کە لەشیان لە پۆڵای ئاسایی (mild steel)، بڕنجی لەحیمکراو (brazed brass) یان ئەلەمنیۆمە. کاتی تاقیکردنەوە کاتی گۆڕین نییە. ڕێساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە."]},{heading:"٥. مەترسییە تایبەتەکان لە کارگەکاندا",body:"کارگە شوێنێکی هەستیارە لەبەر ئەم هۆکارانە:",points:["ماددە کیمیاییەکان: سۆڵڤێنت، ئەلکهول، تینەر — هەموویان پۆلی B ن.","کارەبای ڤۆڵتیەی بەرز: تابلۆ و ترانسفۆرمەر — پۆلی C (NFPA).","تۆزی دار و ئارد: لە هەندێک کارگەدا دەتوانێت تەقینەوەی تۆز (Dust Explosion) دروست بکات.","لەحیمکردن و بڕین: پڕیشکی لەحیمکردن دەتوانێت ئاگری پۆلەکانی A و B دروست بکات.","کۆگای سووتەمەنی: دەبێت لە ژوورێکی تایبەت یان لە دەرەوەی بیناکە بێت، و ئاگرکوژێنەرەوەی گونجاو (کەف یان تۆز) لە نزیکیەوە بێت.","شوێنی دانان: ئاگرکوژێنەرەوەکان لە نزیک دەرگا و ڕاڕەوەکان دابنێ؛ دووریی گەیشتن بە ئاگرکوژێنەرەوەی پۆلی A نابێت لە ٢٣ مەتر (٧٥ پێ) زیاتر بێت، و بۆ شلەمەنییەکان ٩-١٥ مەتر (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"ئاگرکوژێنەرەوە لە کارگەکاندا",description:"ڕێکاری PASS و جۆرەکانی ئاگرکوژێنەرەوە بە ڤیدیۆ"}],quiz:[{question:"بە پیتەکانی NFPA، ئاگرکوژێنەرەوەی CO₂ بۆ کام پۆلەکانی ئاگر گونجاوە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنییە ئاگرگرەکان (B) و ئامێرە کارەباییەکان (C) گونجاوە، چونکە پاشماوە بەجێناهێڵێت و کارەبا ناگوازێتەوە. بەپێی EN 2، C ئاگری گازە و CO₂ بۆ ئەوان نییە."},{question:"لە ڕێکاری PASS دا، دەبێت لوولەی ئاگرکوژێنەرەوەکە بەرەو کوێ بێت؟",options:[{text:"سەری بڵێسەکە",correct:!1},{text:"بنکەی ئاگرەکە",correct:!0},{text:"دوور لە ئاگرەکە",correct:!1},{text:"بنمیچی ژوورەکە",correct:!1}],explanation:"هەمیشە لوولەکە بەرەو بنکەی ئاگرەکە ئاراستە بکە، چونکە سووتەمەنیی ئاگرەکە لەوێیە."},{question:"بۆچی ئاو ناکرێتە سەر ئاگری ڕۆن (پۆلی K)؟",options:[{text:"هیچ کارێک ناکات",correct:!1},{text:"ئاو ڕۆنی سووتاو بڵاو دەکاتەوە و بڵێسەیەکی گەورە دروست دەکات",correct:!0},{text:"ڕۆن ئاوەکە هەڵدەمژێت",correct:!1},{text:"ئاو خۆی دەسووتێت",correct:!1}],explanation:"ئاو لەسەر ڕۆنی داغ یەکسەر دەکوڵێت و ڕۆنی سووتاو فڕێ دەداتە ناو هەوا، و تۆپێکی ئاگرینی گەورە (Fireball) دروست دەبێت. ئاگرکوژێنەرەوەی Wet Chemical یان سەرپۆشێک بەکاربهێنە و گەرماکە ببڕە."}]},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"فریاکەوتنی سەرەتایی و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانی تەواو لەسەر فریاکەوتنی سەرەتایی، CPR و هەڵسوکەوت لە کاتی تەنگانەدا لە کارگەکاندا",blocks:[{body:"فریاکەوتنی سەرەتایی (First Aid) ئەو یارمەتییە سەرەتاییەیە کە پێش گەیشتنی تیمە پزیشکییەکان بە کەسی بریندار یان نەخۆش دەدرێت. لە کارگەکاندا مەترسیی برینداربوون زۆر بەرزە — لە بڕین و سووتانەوە تا کارەبالێدان و کەوتنەخوارەوە لە شوێنی بەرز. هەر کارمەندێک دەبێت بزانێت چۆن پەیوەندی بە ئەمبولانسەوە (١٢٢) بکات، CPR بکات، خوێنبەربوون ڕابگرێت و بریندار بپارێزێت تا ئەمبولانس دەگات. ئەم وانەیە بەپێی ڕێنماییەکانی AHA 2025 و Stop the Bleed ئامادە کراوە."},{heading:"١. پەستانی سنگ و هەناسەدان (CPR) — بە وردی",body:"CPR ڕێکارێکی ڕزگارکردنی ژیانە کاتێک دڵی مرۆڤ دەوەستێت و هەناسەدانی ئاسایی نامێنێت. بەپێی ئەم هەنگاوانە کار بکە:",points:["١. سەلامەتیی شوێن: پێش هەموو شتێک دڵنیا ببەوە کە شوێنەکە سەلامەتە (کارەبا، ئاگر یان گاز نییە)، بۆ ئەوەی تۆ نەبیتە قوربانیی دووەم.",'٢. وەڵامدانەوە: شانەکانی بریندارەکە بە هێز ڕاوەشێنە و بە دەنگی بەرز بپرسە: "باشیت؟ گوێت لێمە؟".',"٣. پەیوەندیکردن: ئەگەر وەڵامی نەدایەوە و هەناسەی نەدا یان تەنها هەناسەی نائاسایی دا، یەکسەر پەیوەندی بە ١٢٢ بکە (یان کەسێک ڕابسپێرە پەیوەندی بکات) و داوا بکە ئامێری AED بهێنرێت.","٤. پەستانی سنگ (Compressions): پاژنەی دەستێک لەسەر ناوەڕاستی سنگ دابنێ (نیوەی خوارەوەی ئێسکی سنگ) و دەستەکەی تر بخە سەری. ٣٠ پەستانی بەهێز و خێرا بدە: قووڵیی ٥-٦ سم، خێرایی ١٠٠-١٢٠ پەستان لە خولەکێکدا، و ڕێگە بدە سنگ بە تەواوی بگەڕێتەوە باری خۆی.","٥. هەناسەدان: سەری بەرەو دواوە ببە و چەناگەی بەرز بکەرەوە، لووتی بگرە و ٢ هەناسە بدە (هەر یەکەیان نزیکەی ١ چرکە، تا سنگ بەرز دەبێتەوە). ئەگەر نەتتوانی یان نەتویست هەناسە بدەیت، تەنها پەستانی سنگ بەردەوام بکە.","٦. بەردەوامی (٣٠:٢): لەسەر ٣٠ پەستان و ٢ هەناسە بەردەوام بە تا ئەمبولانس دەگات، AED ئامادە دەبێت، یان بریندارەکە دەست بە هەناسەدانی ئاسایی دەکات.","٧. بەکارهێنانی AED: هەر کە گەیشت، بیکەرەوە، پەدەکان (Pads) بە سنگی ڕووتەوە بنووسێنە و فەرمانە دەنگییەکانی ئامێرەکە جێبەجێ بکە؛ لە کاتی دانی شۆکدا دەست لە بریندارەکە مەدە."]},{heading:"٢. کۆنترۆڵکردنی خوێنبەربوون (Stop the Bleed)",body:"خوێنبەربوونی توند دەتوانێت لە ماوەیەکی کورتدا مرۆڤ بکوژێت، بۆیە پەیوەندی بە ١٢٢ بکە و بە خێرایی ئەم هەنگاوانە بنێ:",points:["پەستانی ڕاستەوخۆ: پارچە قوماشێکی پاک لەسەر برینەکە دابنێ و بە هەردوو دەست بە هێز پەستان بدە. ئەگەر قوماشەکە پڕ بوو لە خوێن، لای مەبە؛ پارچەیەکی تر بخە سەری و پەستانەکە بەردەوام بکە.","پڕکردنەوەی برین (Wound Packing): ئەگەر برینەکە قووڵ بوو (وەک لە ڕان، بنباڵ یان مل)، قوماشی پاک یان گازی خوێنوەستێنەر بخە ناو برینەکەوە و پڕی بکەرەوە و بە هێز پەستان بدە. ئەندامی بریندار بەرز مەکەرەوە و بە دوای خاڵەکانی پەستاندا (Pressure Points) مەگەڕێ.","تۆرنیکە (Tourniquet): ئەگەر خوێنبەربوونی دەست یان قاچ مەترسیی لەسەر ژیان هەبوو، زوو تۆرنیکە ٥-٧ سم لە سەرووی برینەکەوە (بەرەو لەش) توند ببەستە، کاتەکەی بنووسە، و هەرگیز شلی مەکەرەوە.","شتی چەقیو: ئەگەر ئاسن یان شووشە لە ناو برینەکەدا چەقیبوو، هەرگیز دەری مەهێنە! خوێنبەربوونەکە زیاد دەکات. پەستان لە دەوروبەری بدە و جێگیری بکە."]},{heading:"٣. چارەسەرکردنی سووتان",body:"سووتان لە کارگەکاندا مەترسیدارە؛ بەم شێوەیە مامەڵەی لەگەڵ بکە، و بۆ سووتانی گەورە یان سووتانی دەموچاو و دەستەکان پەیوەندی بە ١٢٢ بکە:",points:["سووتانی گەرمی: یەکسەر ئاوی فێنکی ڕەوان (نەک ئاوی سەهۆڵ) بۆ ماوەی ٢٠ خولەک بەسەر سووتانەکەدا بکە. ئەنگوستیلە و کاتژمێر زوو دابکەنە پێش ئەوەی ئەندامەکە بئاوسێت.","سووتانی کیمیایی: جلە پیسبووەکان دابکەنە و پێست بە ئاوێکی زۆری ڕەوان بۆ ماوەی ٢٠ خولەک یان زیاتر بشۆ، و پەڕەی SDS ی ماددەکە بپشکنە.","سووتانی کارەبا: یەکەم کار کارەبا ببڕە! پاشان سووتانەکە وەک سووتانی گەرمی سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە، چونکە کارەبا دەتوانێت زیان بە دڵ و ناو لەش بگەیەنێت.","ئاگاداری: بڵقی سووتان مەتەقێنە، و سەهۆڵ، چەوری، هەویری ددان یان مەرهەم بەبێ ڕێنماییی پزیشکی بەکارمەهێنە."]},{heading:"٤. شکان و برینداربوونی بڕبڕەی پشت",body:"لە کاتی کەوتنەخوارەوە لە شوێنی بەرز یان گومانی شکان:",points:["جێگیرکردن (Splinting): ئەگەر گومانی شکان هەبوو، ئەندامی بریندار مەجووڵێنە. وەک خۆی، بە دارێک یان کارتۆنێک جێگیری بکە بۆ ئەوەی ئازارەکە کەم ببێتەوە.","پاراستنی پشت و مل: ئەگەر کەسێک لە شوێنێکی بەرز کەوتە خوارەوە، مەیجووڵێنە مەگەر شوێنەکە مەترسیدار بێت (وەک ئاگر)، چونکە جووڵاندن دەتوانێت ببێتە هۆی ئیفلیجبوون. سەری جێگیر ڕابگرە و پەیوەندی بە ١٢٢ بکە.","ساردکردنەوە: بۆ کەمکردنەوەی ئاوسان (Swelling)، سەهۆڵ لە پارچە قوماشێکدا بپێچە و بۆ ماوەی ٢٠ خولەک لەسەر شوێنی ئازارەکە دابنێ؛ سەهۆڵ ڕاستەوخۆ لەسەر پێست دامەنێ."]},{heading:"٥. کارەبالێدان و ڕزگارکردن",body:"کارەبا دەتوانێت دڵ بوەستێنێت؛ ئەم ڕێکارانە جێبەجێ بکە:",points:["یەکسەر کارەبا ببڕە: تا کارەبا نەبڕدرێت دەست لە بریندارەکە مەدە، چونکە کارەبا تۆش دەگرێت.","جیاکردنەوەی سەلامەت: ئەگەر نەتتوانی کارەبا ببڕیت و ڤۆڵتیە نزم بوو، بە دارێکی وشک یان پلاستیک وایەرەکە لە بریندارەکە دوور بخەرەوە و لەسەر شتێکی وشک بوەستە. لە هێڵەکانی ڤۆڵتیەی بەرز نزیک مەبەرەوە و پەیوەندی بە ١١٥ بکە.","پشکنینی پزیشکی: هەموو ئەو کەسانەی کارەبایان لێداوە، تەنانەت ئەگەر هەست بە باشی بکەن، دەبێت بچنە نەخۆشخانە بۆ پشکنینی دڵ؛ پەیوەندی بە ١٢٢ بکە."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"CPR و فریاکەوتنی سەرەتایی",description:"ڕاهێنانی CPR و یارمەتیدانی بریندارەکان لە کارگەکاندا"}],quiz:[{question:"لە CPR دا، دەبێت خێرایی پەستانی سنگ لە خولەکێکدا چەند بێت؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٥٠+",correct:!1}],explanation:"بەپێی AHA 2025، خێرایی پەستان ١٠٠-١٢٠ پەستانە لە خولەکێکدا، بە قووڵیی ٥-٦ سم بۆ گەورەسالان، بۆ ئەوەی خوێن بگاتە مێشک."},{question:"ئەگەر شتێکی تیژ لە ناو برینێکدا چەقیبوو، چی دەکەیت؟",options:[{text:"دەری دەهێنم",correct:!1},{text:"لە شوێنی خۆی دەیهێڵمەوە و پەیوەندی بە ١٢٢ دەکەم",correct:!0},{text:"دەستم لێی دوور دەخەمەوە و هیچ ناکەم",correct:!1},{text:"بە ئاو دەیشۆم",correct:!1}],explanation:"دەرهێنانی شتەکە خوێنبەربوونەکە زیاد دەکات. دەبێت لە شوێنی خۆی بمێنێتەوە و جێگیر بکرێت تا پزیشک لە نەخۆشخانە دەری دەهێنێت."},{question:"ئەگەر کارەبا کەسێکی گرتبوو، یەکەم کار کە دەیکەیت چییە؟",options:[{text:"دەستی دەگرم",correct:!1},{text:"CPR دەکەم",correct:!1},{text:"کارەبا دەبڕم",correct:!0},{text:"ئاوی بەسەردا دەکەم",correct:!1}],explanation:"دەبێت یەکەم جار سەرچاوەی کارەبا ببڕدرێت بۆ ئەوەی کارەبا تۆش نەگرێت؛ پاشان پەیوەندی بە ١٢٢ بکە و ئەگەر پێویست بوو دەست بە CPR بکە."}]},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"ماددە کیمیاییەکان (SDS)",subtitle:"Chemical Safety & Labelling",summary:"مامەڵەکردن لەگەڵ ماددە کیمیاییەکان و ناسینی مەترسییەکانیان",blocks:[{body:"ماددە کیمیاییەکان لە کارگەکاندا دەتوانن ببنە هۆی سووتانی پێست، ژەهراویبوون، ئاگر یان تەقینەوە."},{heading:"١. پەڕەی SDS چییە؟",body:"پەڕەی زانیاریی سەلامەتی (Safety Data Sheet — SDS) زانیاریی هەر ماددەیەک لە ١٦ بەشدا دەدات، لەوانە:",points:["پێکهاتەی ماددەکە و مەترسییەکانی.","کام PPE پێویستە (دەمامک، دەستکێش، چاویلکە).","فریاکەوتنی سەرەتایی ئەگەر ماددەکە بەر لەش کەوت، و ڕێگاکانی کوژاندنەوەی ئاگر."]},{heading:"٢. هێماکانی GHS",body:"هەندێک لە نیشانەکانی سەر قوتوو و دەبەکان:",points:["بڵێسە (Flame): ماددەی ئاگرگر.","کەللەسەر و ئێسک (Skull and Crossbones): ماددەی ژەهراویی کوشندە.","داخوران (Corrosion): ماددەی ترش (ئەسید) یان ئەلکالی کە پێست و کانزاکان دەخوات."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"SDS",description:"نیشانەکانی مەترسیی GHS"}],quiz:[{question:"لە کوێ دەتوانین بزانین کام دەمامک بۆ ماددەیەکی کیمیایی پێویستە؟",options:[{text:"لە نیشانەکانی سەر دیوار",correct:!1},{text:"لە پەڕەی SDS دا",correct:!0},{text:"لە هاوڕێکەت بپرسە",correct:!1},{text:"پێویستی بە دەمامک نییە",correct:!1}],explanation:"پەڕەی SDS هەموو زانیارییەکانی پاراستنی تایبەت بەو ماددەیە دەدات، لەوانە جۆری PPE ی پێویست (بەشی ٨)."}]},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"کارکردن لە شوێنی بەرز",subtitle:"Fall Protection & Ladders",summary:"ڕێگرتن لە کەوتنەخوارەوە لە داربەست، بان و پەیژە",blocks:[{body:"کەوتنەخوارەوە لە شوێنی بەرز یەکێکە لە هۆکارە سەرەکییەکانی مردن لە کارگە و شوێنەکانی بیناسازیدا."},{heading:"١. پاراستن دژی کەوتنەخوارەوە",body:"هەر کارێک لە بەرزیدا (OSHA: لە ١٫٢ مەترەوە لە کارگەکاندا و لە ١٫٨ مەترەوە لە بیناسازیدا) پێویستی بەم شتانە هەیە:",points:["هارنەس (Full Body Harness): بە دروستی و توندی لەبەرکردنی.","پەتی سەلامەتی (Lanyard): دەبێت بە خاڵێکی بەستنەوەی پتەوەوە (Anchor Point) بەسترابێت.","ڕێلی پاراستن (Guardrails): لە دەوروبەری داربەست، بان و لێوارە کراوەکاندا."]},{heading:"٢. سەلامەتیی پەیژە (Ladders)",body:"یاسای ٣ خاڵی پەیوەندی:",points:["هەمیشە دەبێت ٣ ئەندامی لەش (دوو پێ و دەستێک، یان دوو دەست و پێیەک) لەسەر پەیژەکە بن.","گۆشەی دانانی پەیژە دەبێت ٤:١ بێت (بۆ هەر ٤ مەتر بەرزی، بنی پەیژەکە مەترێک لە دیوارەکە دوور بێت)."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"کارکردن لە بەرزیدا",description:"بەکارهێنانی هارنەس"}],quiz:[{question:"یاسای ٣ خاڵ لەسەر پەیژە واتای چییە؟",options:[{text:"٣ کەس پێکەوە لەسەری بن",correct:!1},{text:"٣ خولەک لەسەری بمێنەوە",correct:!1},{text:"هەمیشە ٣ ئەندامی لەش بە پەیژەکەوە بن",correct:!0},{text:"پەیژەکە بە ٣ پەت ببەستەوە",correct:!1}],explanation:"یاسای ٣ خاڵ بۆ ئەوەیە کە کرێکار هاوسەنگیی خۆی لەدەست نەدات و نەکەوێتە خوارەوە."}]},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"شوێنە تەسک و داخراوەکان",subtitle:"Confined Space Safety",summary:"کارکردن لە ناو تانکی، بۆری و مەنهۆڵەکاندا",blocks:[{body:"شوێنە داخراوەکان مەترسیدارن چونکە هەوا تێیاندا ناگۆڕدرێت، ئۆکسجین دەتوانێت کەم ببێتەوە و گازە کوشندەکان تێیاندا کۆ دەبنەوە."},{heading:"١. مەترسییە سەرەکییەکان",body:"پێش ئەوەی بچیتە ژوورەوە، بزانە:",points:["کەمیی ئۆکسجین (کەمتر لە ١٩٫٥٪): دەبێتە هۆی خنکان.","گازە ژەهراوییەکانی وەک CO (بێ بۆن) و H₂S (کە لە چڕیی بەرزدا هەستی بۆنکردن پەک دەخات).","مەترسیی ئاگر و تەقینەوە ئەگەر گاز یان هەڵمی ئاگرگر هەبێت."]},{heading:"٢. ڕێکارەکانی چوونە ژوورەوە",body:"دەبێت ئەم مەرجانە هەبن:",points:["پشکنینی هەوا بە ئامێری پێوانی گاز (Gas Monitor) پێش چوونە ژوورەوە و لە کاتی کاردا.","بوونی چاودێرێک (Attendant) کە لە دەرەوە بمێنێتەوە، چاوی لەسەر کرێکاری ناوەوە بێت، و بە هیچ شێوەیەک نەچێتە ژوورەوە.","مۆڵەتی کار (Permit)، ئامرازەکانی پەیوەندی و پلانی ڕزگارکردن دەبێت ئامادە بن."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"شوێنە داخراوەکان",description:"پشکنینی هەوا"}],quiz:[{question:"ئایا دروستە چاودێری دەرەوە بەبێ ئامێر بچێتە ژوورەوە بۆ ڕزگارکردنی هاوڕێکەی؟",options:[{text:"بەڵێ، لەبەر مرۆڤایەتی",correct:!1},{text:"نەخێر، چونکە ئەویش دەخنکێت",correct:!0},{text:"بەڵێ، ئەگەر هەناسەی خۆی ڕابگرێت",correct:!1},{text:"هیچ کامیان نییە",correct:!1}],explanation:"بەپێی لێکۆڵینەوەکانی NIOSH، بەشێکی گەورە لە مردنەکانی شوێنە داخراوەکان ئەو کەسانەن کە بەبێ ئامێر و ڕاهێنان چوونەتە ژوورەوە بۆ ڕزگارکردن. چاودێر دەبێت پەیوەندی بە تیمی ڕزگارکردن و ١١٥ ەوە بکات."}]},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"دەنگ و پاراستنی گوێ",subtitle:"Hearing Conservation",summary:"پاراستن دژی ژاوەژاوی ئامێرە گەورەکان",blocks:[{body:"کەڕبوون یان کەمبوونەوەی بیستن بەهۆی دەنگی کارگەکانەوە هێواش هێواش ڕوودەدات و چارەسەر نابێت."},{heading:"١. ئاستەکانی دەنگ",body:"کەی دەنگ دەبێتە مەترسی؟",points:["٨٥ dB(A): سنووری دەستپێکردنی مەترسی بۆ ٨ کاتژمێری کار.","١٠٠ dB(A): بەبێ پاراستن تەنها بۆ ١٥ خولەک لە ڕۆژێکدا سەلامەتە (NIOSH).","نیشانە: ئەگەر دوای کار هەستت بە زرنگانەوە (Tinnitus) لە گوێکانتدا کرد، دەنگەکە زۆر بەرز بووە."]},{heading:"٢. کەرەستەکانی پاراستن",body:"کەرەستەکانی پاراستنی گوێ (Hearing Protection Devices — HPD):",points:["پارێزەری ناو گوێ (Earplugs): ئەگەر بە دروستی دابنرێن، پاراستنێکی باش دەدەن.","پارێزەری سەر گوێ (Earmuffs): بە ئاسانی لەبەر دەکرێن و بۆ دەنگی بەرز گونجاون.","بەکارهێنانی هەردووکیان پێکەوە لە شوێنە زۆر بەدەنگەکاندا."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"دەنگ",description:"چۆن پارێزەری گوێ بەکاردەهێنیت؟"}],quiz:[{question:"ئەگەر دەنگ گەیشتە ١٠٠ dB(A)، بەپێی NIOSH چەند کات دەتوانیت بەبێ پارێزەری گوێ بمێنیتەوە؟",options:[{text:"١ کاتژمێر",correct:!1},{text:"١٥ خولەک",correct:!0},{text:"٤ کاتژمێر",correct:!1},{text:"هەموو ڕۆژەکە",correct:!1}],explanation:"بەپێی NIOSH، هەر ٣ dB زیادبوون کاتی سەلامەت دەکاتە نیوە: ٨٥ dB(A) بۆ ٨ کاتژمێر، و ١٠٠ dB(A) تەنها بۆ ١٥ خولەک."}]},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"هەڵگرتنی بار (Ergonomics)",subtitle:"Safe Lifting Techniques",summary:"ڕێگرتن لە ئازاری پشت و ماسولکەکان",blocks:[{body:"برینداربوونی پشت یەکێکە لە بڵاوترین برینەکان لە کارگەکاندا، بەهۆی هەڵگرتنی هەڵەی بارەوە."},{heading:"١. ڕێگای دروستی هەڵگرتن",body:"جێبەجێکردنی ئەم هەنگاوانە پشت دەپارێزێت:",points:["ئەژنۆکانت بچەمێنەوە: هێزی قاچەکانت بەکاربهێنە، نەک هی پشت.","بارەکە لە لەشت نزیک بکەرەوە: هەتا بارەکە لێت دوورتر بێت، پەستان لەسەر پشت زیاتر دەبێت.","پشتت ڕاست ڕابگرە: کاتێک شتێکی قورس هەڵدەگریت، پشتت مەچەمێنەوە.","لەشت با مەدە: ئەگەر ویستت بارەکە بەرەو لایەک ببەیت، بە پێکانت هەموو لەشت بسووڕێنە."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"هەڵگرتنی بار",description:"شێوازی دروست"}],quiz:[{question:"لە کاتی هەڵگرتنی شتێکی قورسدا، دەبێت هێز لەسەر چی بێت؟",options:[{text:"پشت",correct:!1},{text:"ماسولکەکانی قاچ",correct:!0},{text:"شان",correct:!1},{text:"تەنها دەست",correct:!1}],explanation:"ماسولکەکانی قاچ بەهێزترن و پشت لە برینداربوون دەپارێزن."}]},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"گاز و هەواگۆڕین",subtitle:"Ventilation & Toxic Gases",summary:"کۆنترۆڵکردنی هەوا و گازە ژەهراوییەکان",blocks:[{body:"هەواگۆڕینی دروست لە کارگەدا گرنگە بۆ ڕێگرتن لە کۆبوونەوەی تۆز و ئەو گازانەی دەبنە هۆی نەخۆشییەکانی هەناسە."},{heading:"١. مۆنۆکسیدی کاربۆن (CO)",body:"گازی کوشندەی بێدەنگ:",points:["بێ ڕەنگ و بێ بۆنە.","لە سووتانی سووتەمەنی و بزوێنەرەکانی بەنزین و دیزڵەوە (وەک مۆلیدە و فۆرکلیفت) دروست دەبێت.","نیشانەکان: سەرئێشە، سەرگێژخواردن، دڵتێکهەڵهاتن و بێهۆشبوون. ئەگەر هەستت بەم نیشانانە کرد، یەکسەر بچۆ دەرەوە و پەیوەندی بە ١٢٢ بکە."]},{heading:"٢. جۆرەکانی هەواگۆڕین",body:"هەوا چۆن دەگۆڕدرێت؟",points:["هەواگۆڕینی سروشتی: دەرگا و پەنجەرە کراوەکان.","هەواگۆڕینی دەستکرد: پانکە و سیستەمەکانی ڕاکێشانی هەوا (Local Exhaust).","پاراستنی کەسی: دەمامکی فلتەردار بەپێی SDS؛ بەڵام دەمامکی فلتەری دژی CO و کەمیی ئۆکسجین ناپارێزێت."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"گاز",description:"گازی CO"}],quiz:[{question:"بۆچی گازی CO مەترسیدارە؟",options:[{text:"چونکە بۆنەکەی ناخۆشە",correct:!1},{text:"چونکە نابینرێت و بۆنی ناکرێت",correct:!0},{text:"چونکە ڕەنگەکەی سوورە",correct:!1},{text:"چونکە تەنها بە شەو دروست دەبێت",correct:!1}],explanation:"لەبەر ئەوەی هەستی پێ ناکرێت، کرێکاران بێ ئەوەی بزانن ژەهراوی دەبن. ئامێری دۆزینەوەی CO (CO Detector) لەو شوێنانە دابنێ کە بزوێنەریان تێدا کار دەکات."}]},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"دەرچوونی بەپەلە (Evacuation)",subtitle:"Emergency Assembly Points",summary:"پلانی چوونە دەرەوە لە کاتی ئاگر یان کارەساتدا",blocks:[{body:"زانینی ڕێگای دەرچوون دەتوانێت جیاوازی لە نێوان ژیان و مردندا دروست بکات."},{heading:"١. یاساکانی دەرچوون",body:"کاتێک زەنگی مەترسی لێدەدات:",points:["بە هێمنی و خێرایی بڕۆ، ڕامەکە و ئاسانسۆر بەکارمەهێنە.","دەرگاکان لە دوای خۆتەوە دابخە بۆ ئەوەی ئاگر و دووکەڵ بڵاو نەبنەوە، بەڵام قوفڵیان مەکە.","بەرەو خاڵی کۆبوونەوە (Assembly Point) بڕۆ بۆ ئەوەی کارمەندان بژمێردرێن.","بە هیچ شێوەیەک مەگەڕێوە ژوورەوە تا بەرپرسی سەلامەتی یان تیمەکانی ١١٥ ڕێگە نەدەن."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"مەشقی دەرچوون",description:"ڕاهێنان لەسەر دەرچوون"}],quiz:[{question:"کاتێک زەنگی مەترسی لێدەدات، چی دەکەیت؟",options:[{text:"کۆکردنەوەی کەلوپەلەکانم",correct:!1},{text:"بە هێمنی بەرەو دەرچوون ڕۆیشتن",correct:!0},{text:"خۆشاردنەوە لە ژێر مێز",correct:!1},{text:"هاوارکردن",correct:!1}],explanation:"دەرچوونی هێمن و خێرا باشترین ڕێکارە بۆ پاراستنی ژیان."}]},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"سەلامەتیی لەحیمکردن",subtitle:"Welding & Cutting Hazards",summary:"پاراستن لە تیشک، گەرما و دووکەڵی لەحیمکردن",blocks:[{body:"کاری لەحیمکردن مەترسیی تیشکی سەروو وەنەوشەیی (UV)، سووتانی سەخت، و گاز و دووکەڵی ژەهراویی تێدایە."},{heading:"١. پاراستنی چاو و پێست",body:"پێداویستییەکانی لەحیمکاران:",points:["کڵاوی پاراستنی لەحیمکردن (Welding Helmet) بە فلتەری گونجاو: بۆ پاراستنی چاو لە تیشکی UV و ڕووناکیی توندی کەوانەی لەحیمکردن (Arc).","دەستکێشی چەرمی درێژ: بۆ پاراستن لە گەرما و پڕیشک.","پێشبەندی چەرمی (Apron): بۆ پاراستنی لەش."]},{heading:"٢. مەترسیی ئاگر (Hot Work)",body:"پێش دەستپێکردن مۆڵەتی کاری گەرم (Hot Work Permit) وەربگرە و:",points:["دەوروبەری شوێنی کار لە ماددە ئاگرگرەکان پاک بکەرەوە (NFPA 51B: بە دووریی ١١ مەتر / ٣٥ پێ)، یان بە پەردەی بەرگر دایانبپۆشە.","ئاگرکوژێنەرەوەیەکی گونجاو لە نزیک خۆت ئامادە بکە.","چاودێری ئاگر (Fire Watch): لە کاتی کاردا و لانیکەم ١ کاتژمێر دوای تەواوبوونی کار لە شوێنەکە دەمێنێتەوە؛ پاشان شوێنەکە تا ٣ کاتژمێری تر چاودێری دەکرێت، بەپێی بڕیاری بەرپرسی مۆڵەتەکە (NFPA 51B)."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"لەحیمکردن",description:"لەبەرکردنی دروست"}],quiz:[{question:"بۆچی دوای لەحیمکردن چاودێری ئاگر لانیکەم ١ کاتژمێر لە شوێنەکە دەمێنێتەوە؟",options:[{text:"بۆ پاککردنەوە",correct:!1},{text:"بۆ ئەوەی ئاگرێکی شاراوە دروست نەبێت",correct:!0},{text:"بۆ ساردکردنەوەی ئاسنەکە",correct:!1},{text:"هیچ پێویست نییە",correct:!1}],explanation:"زۆر جار پڕیشک دەکەونە ناو درز و کەرەستەکانەوە و دوای ماوەیەک ئاگر دروست دەکەن. بەپێی NFPA 51B (چاپی ٢٠١٩ و دواتر)، چاودێری لانیکەم ١ کاتژمێر دوای کار بەردەوام دەبێت."}]},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"ئامێرەکانی گواستنەوە",subtitle:"Forklift & Vehicle Safety",summary:"سەلامەتیی فۆرکلیفت و لێخوڕین لە کارگەدا",blocks:[{body:"فۆرکلیفت ئامێرێکی قورسە و مەترسیی پلیشاندنەوە و وەرگەڕانی هەیە ئەگەر بە دروستی لێنەخوڕدرێت."},{heading:"١. یاساکانی لێخوڕین",body:"بۆ شۆفێرانی فۆرکلیفت:",points:["تەنها کەسانی ڕاهێنراو و مۆڵەتدار دەتوانن فۆرکلیفت لێبخوڕن (OSHA 1910.178).","هەرگیز کەس لەسەر چنگاڵەکانی (Forks) فۆرکلیفت یان لە تەنیشت خۆت هەڵمەگرە.","بار لە توانای ئامێرەکە زیاتر مەکە بۆ ئەوەی وەرنەگەڕێت، و پشتێنی سەلامەتی ببەستە.","لە هەر سووچێک یان دەرگایەکدا خێرایی کەم بکەرەوە و هۆڕن (Horn) لێبدە."]},{heading:"٢. سەلامەتیی پیادەکان",body:"ئەگەر لە نزیک فۆرکلیفتەوە دەڕۆیت:",points:["چاوت لە شۆفێرەکە بێت (Eye Contact) و دوورییەکی سەلامەت بهێڵەوە.","لە ڕاڕەوە دیاریکراوەکانی پیادەدا بڕۆ."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"فۆرکلیفت",description:"ناسینی خاڵە نادیارەکان (Blind Spots)"}],quiz:[{question:"ئەگەر شۆفێری فۆرکلیفت بارێکی بەرزی هەبێت و پێشی خۆی نەبینێت، چی دەکات؟",options:[{text:"بە خێرایی لێدەخوڕێت",correct:!1},{text:"بە پاشەوە (Reverse) لێدەخوڕێت",correct:!0},{text:"هۆڕن لێدەدات و چاوەکانی دەنووقێنێت",correct:!1},{text:"هیچ کامیان نییە",correct:!1}],explanation:"کاتێک بار ڕێگری لە بینینی شۆفێر دەکات، دەبێت بە پاشەوە لێبخوڕێت بۆ ئەوەی ڕێگاکەی ببینێت (OSHA 1910.178)."}]},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"نیشانەکانی سەلامەتی",subtitle:"Safety Signs & Symbols",summary:"ناسینی ڕەنگ و هێماکانی سەلامەتی (ISO 7010)",blocks:[{body:"نیشانەکانی سەلامەتی بە زمانێکی جیهانی ئاگادارمان دەکەنەوە لە مەترسییەکان."},{heading:"١. واتای ڕەنگەکان (ISO 7010)",body:"هەر ڕەنگێک پەیامێکی تایبەت دەگەیەنێت:",points:["سوور: قەدەغەکردن یان ئامێرەکانی ئاگرکوژاندنەوە (نموونە: جگەرەکێشان قەدەغەیە).","زەرد: ئاگاداری و مەترسی (نموونە: مەترسیی کارەبا).","شین: ناچاری (نموونە: دەبێت کڵاوی پاراستن لەبەر بکەیت).","سەوز: سەلامەتی و دەرچوون (نموونە: دەرگای دەرچوون)."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"نیشانەکانی سەلامەتی",description:"هێما ستانداردەکان"}],quiz:[{question:"نیشانەیەکی ڕەنگ زەرد واتای چییە؟",options:[{text:"قەدەغەکردن",correct:!1},{text:"ئاگاداری و مەترسی",correct:!0},{text:"شوێنی سەلامەت",correct:!1},{text:"بەکارهێنانی ئاو",correct:!1}],explanation:'ڕەنگی زەرد هەمیشە واتای "ئاگادار بە" یان "مەترسی هەیە".'}]},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"پاکوخاوێنی (Housekeeping)",subtitle:"Order & Maintenance",summary:"ڕێکخستنی شوێنی کار بۆ کەمکردنەوەی مەترسییەکان",blocks:[{body:"شوێنی کاری پاک شوێنێکی سەلامەتە. زۆرێک لە ڕووداوەکان بەهۆی خلیسکان و پێهەڵکەوتن بە کەرەستە پەرشوبڵاوەکانەوە ڕوودەدەن."},{heading:"١. یاسا گشتییەکان",body:"بۆ هەموو کرێکاران:",points:["پاککردنەوەی ڕۆن یان ئاوی ڕژاو لە زووترین کاتدا.","کۆکردنەوەی پاشماوەکان لە سەبەتە تایبەتەکاندا.","هێشتنەوەی ڕاڕەو و دەرچوونەکان بە کراوەیی و بێ ڕێگر.","گەڕاندنەوەی هەر ئامێرێک بۆ شوێنی خۆی دوای تەواوبوونی کار."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"پاکوخاوێنی",description:"نموونەی شوێنێکی پاک"}],quiz:[{question:"ئەگەر بینیت ڕۆن لەسەر زەوی ڕژاوە، چی دەکەیت؟",options:[{text:"جێی دەهێڵم تا پاککەرەوە دێت",correct:!1},{text:"پاکی دەکەمەوە یان نیشانەیەکی لێ دادەنێم و ئاگاداریان دەکەمەوە",correct:!0},{text:"بەسەریدا باز دەدەم",correct:!1},{text:"گوێی پێ نادەم",correct:!1}],explanation:"هەر کرێکارێک بەرپرسە لە پاکی و سەلامەتیی شوێنی کاری خۆی، بۆ ئەوەی کەس نەکەوێت."}]},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"بوومەلەرزە لە کارگەکاندا",subtitle:"Earthquake Safety in Factories",summary:"سەلامەتیی کرێکاران لە کاتی بوومەلەرزە و دوای ئەو",blocks:[{body:"بوومەلەرزە لە کارگەکاندا مەترسییەکی دووقات دروست دەکات: هەم خودی لەرزینەکە، و هەم کەوتنی ئامێرە قورسەکان، ڕژانی ماددە کیمیاییەکان، شکانی بۆرییەکان و دزەکردنی گاز. دەبێت هەر کارگەیەک پلانێکی بوومەلەرزەی هەبێت."},{heading:"١. خۆت بدە بە زەویدا، خۆت بپارێزە، خۆت بگرە (Drop, Cover, Hold On)",body:"لە کاتی بوومەلەرزەدا:",points:["خۆت بدە بە زەویدا (Drop) و بچۆ ژێر مێزێک یان مێزی کارێکی (Workbench) پتەو — دوور لە ئامێرە قورسەکان، ڕەفەکان و شووشە.","ئەگەر مێز نەبوو، لە تەنیشت دیوارێکی ناوەوە لەسەر ئەژنۆ دابنیشە و سەر و ملت بە دەستەکانت داپۆشە (Cover).","مێزەکە توند بگرە (Hold On) تا لەرزینەکە بە تەواوی دەوەستێت.","ڕامەکە و مەچۆ ژێر ئامێرەکان یان لای ڕەفەکان! ئامێرە قورسەکان و ڕەفەکان دەتوانن بجووڵێن یان بکەونە سەرت."]},{heading:"٢. دوای بوومەلەرزە",body:"دوای ئەوەی لەرزینەکە وەستا:",points:["ئامێرەکان بۆ زیان بپشکنە، و ئامێرە زیانلێکەوتووەکان هەڵمەکە تا دەپشکنرێن.","بزانە ئایا ماددە کیمیاییەکان ڕژاون یان نا، و لێیان دوور بکەوەرەوە.","ئەگەر بۆنی گاز هات — بە خێرایی دەربچۆ، کارگەکە چۆڵ بکە، و لە دەرەوە پەیوەندی بە ١١٥ بکە.","گاز تەنها ئەو کاتە ببڕە کە بۆنی هات یان دەنگی دزەکردنی هات؛ کارەبا ببڕە ئەگەر زیان بە وایەر یان تابلۆکان گەیشتبێت.","پێش گەڕانەوە بۆ ژوورەوە، دەبێت ئەندازیارێک بینای کارگەکە بۆ درز بپشکنێت."]},{heading:"٣. ئامادەباشی",body:"پلانی پێشوەخت:",points:["بۆ هەر بەشێک پلانی بوومەلەرزە ئامادە بکە.","ئامێرە قورسەکان بە زنجیر یان بۆڵت جێگیر بکە.","دەبە و قوتووە کیمیاییەکان لەسەر ڕەفی نزم و جێگیر دابنێ.","ڕاڕەوەکانی دەرچوون هەمیشە کراوە بن.","هەر ٦ مانگ جارێک مەشق بکە."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"بوومەلەرزە",description:"بوومەلەرزە لە کارگەدا"}],quiz:[{question:"لە کاتی بوومەلەرزەدا لە کارگەیەکدا، یەکەم کار چییە؟",options:[{text:"ڕاکردن بەرەو دەرەوە",correct:!1},{text:"خۆت بدە بە زەویدا و بچۆ ژێر مێزێکی پتەو",correct:!0},{text:"ئامێرەکان بکوژێنەرەوە",correct:!1},{text:"بچۆ نزیک پەنجەرەکان",correct:!1}],explanation:"خۆت بدە بە زەویدا، خۆت بپارێزە، خۆت بگرە — یەکەم ڕێکارە لە ناو بیناکاندا، دوور لە ئامێر، ڕەف و شووشە."},{question:"دوای بوومەلەرزە لە کارگەیەکی کیمیاییدا، یەکەم پشکنین چییە؟",options:[{text:"کارەبا",correct:!1},{text:"ڕژانی ماددە کیمیاییەکان",correct:!0},{text:"ئاو",correct:!1},{text:"تەلەفۆن",correct:!1}],explanation:"ڕژانی ماددە کیمیاییەکان مەترسییەکی گەورەیە دوای بوومەلەرزە و پێویستە بە خێرایی بپشکنرێت."}]},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"لافاو و ئاوگرتن",subtitle:"Flood Emergency in Industrial Areas",summary:"پاراستنی کارگە و کرێکاران لە کاتی لافاودا",blocks:[{body:"لافاو دەتوانێت کارگەکان بە تەواوی وێران بکات: ئامێرەکان تێکبدات، ماددە کیمیاییەکان بڵاو بکاتەوە و کارەبا بکاتە مەترسی. ئەو کارگانەی لە نزیک ڕووبار و دۆڵەکانن زیاتر لە مەترسیدان."},{heading:"١. پێش لافاو",body:"ئامادەباشی:",points:["ئاگادارکردنەوەکانی کەشناسی (Meteorology) بەدواداچوون بۆ بکە.","کەرەستە گرنگەکان و ماددە کیمیاییەکان بگوازەرەوە بۆ شوێنێکی بەرز.","سیستەمی کارەبا بۆ بڕینی خۆکار (Auto-shutoff) ئامادە بکە.","کیسەی لم (Sandbags) لەبەردەم دەرگاکان و بناغەی کارگەکە دابنێ."]},{heading:"٢. لە کاتی لافاودا",body:"ڕێکارە بەپەلەکان:",points:["ئەگەر بە سەلامەتی توانیت و ئاو نەگەیشتبووە تابلۆکانی کارەبا، کارەبا و گاز ببڕە؛ لە ناو ئاودا دەست لە کارەبا مەدە!","مەچۆ ناو ئاوی لافاوەوە — ١٥ سم ئاوی خێرا دەتوانێت مرۆڤ بخات، و ٣٠ سم دەتوانێت ئۆتۆمبێل ببات.","بچۆ شوێنێکی بەرز — نهۆمی دووەم یان سەربان.","پەیوەندی بە ١١٥ بکە و لە شوێنی خۆت بمێنەوە تا تیمەکانی ڕزگارکردن دەگەن."]},{heading:"٣. دوای لافاو",body:"گەڕانەوە و پاککردنەوە:",points:["مەچۆ ناو کارگەکە تا ئەندازیار دڵنیا نەبێتەوە کە بیناکە سەلامەتە.","دەست لە ماددە کیمیاییە ئاوتێکەوتووەکان مەدە — لە ڕێگەی ١١٥ ەوە داوای تیمی ماددە مەترسیدارەکان (HazMat) بکە.","کارەبا هەڵمەکە تا سیستەمەکە لەلایەن کارەباچییەکی شارەزاوە دەپشکنرێت.","وێنەی هەموو زیانەکان بگرە بۆ بیمە و ڕاپۆرت."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"لافاو",description:"لافاو لە کارگەدا"}],quiz:[{question:"لە کاتی لافاودا لە کارگەیەکدا، یەکەم کار چییە؟",options:[{text:"ئامێرەکان بپارێزە",correct:!1},{text:"کارەبا و گاز ببڕە، ئەگەر بە سەلامەتی توانیت",correct:!0},{text:"بڕۆ بۆ ماڵەوە",correct:!1},{text:"ئاوەکە بە پەمپ دەربکێشە",correct:!1}],explanation:"کارەبا و گاز یەکەم مەترسییەکانن لە کاتی لافاودا؛ بەڵام ئەگەر ئاو گەیشتبووە تابلۆکان، نزیک مەبەرەوە و بچۆ شوێنێکی بەرز."}]},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"وەڵامدانەوەی بەرگریی شارستانی لە کارگەکاندا",subtitle:"Industrial CD Response & Multi-Agency Coordination",summary:"پێکهێنانی تیمی وەڵامدانەوەی کارگە لە کاتی ڕووداوەکاندا و هەماهەنگی لەگەڵ ١١٥",blocks:[{body:"کارگە گەورەکان (نەوت، گاز، کیمیا، پۆڵا) دەبێت تیمی تایبەتی خۆیان بۆ وەڵامدانەوەی تەنگانە هەبێت کە پێش گەیشتنی تیمەکانی ١١٥ کار بکەن. ستانداردی NFPA 600 (Facility Fire Brigades) ڕێکخستن، ڕاهێنان و ئامێرەکانی تیمەکانی ئاگرکوژاندنەوەی کارگەکان دیاری دەکات. یەکەم خولەکەکانی ڕووداو زۆر گرنگن، بۆیە تیمی کارگە دەبێت ئامادە و ڕاهێنراو بێت."},{heading:"١. پێکهێنانی تیمی وەڵامدانەوەی کارگە (ERT)",body:"بنەما سەرەکییەکانی تیمی وەڵامدانەوەی تەنگانە (Emergency Response Team):",points:["قەبارەی تیم: بەپێی هەڵسەنگاندنی مەترسییەکانی کارگە و ئەرکەکانی تیم دیاری دەکرێت؛ NFPA 600 ڕێژەیەکی جێگیری ئەندامان بەرامبەر ژمارەی کارمەندان دیاری ناکات.","ڕاهێنان: بەپێی ئەرکەکانی هەر ئەندامێک، لەگەڵ ڕاهێنانی نوێکردنەوە (Refresher) لانیکەم ساڵی جارێک.","فەرماندەی ڕووداو (Incident Commander — IC): تەنها یەک کەس فەرمان دەدات، بۆ ئەوەی فەرمانەکان تێکەڵ نەبن.","ئەرکە سەرەکییەکان: کوژاندنەوەی ئاگر، ڕزگارکردن، فریاکەوتنی سەرەتایی و چۆڵکردنی بینا.","پەیوەندی: بێتەل (Radio) بە کەناڵێکی تایبەت، و مۆبایل وەک ڕێگای یەدەگ.","کاتی وەڵامدانەوە: لە پلانەکەدا دیاری بکە، بە مەشق بیپێوە و باشتری بکە.","پێشنیار: خولەکانی ICS-100 و ICS-200 (FEMA) بۆ فێربوونی سیستەمی فەرماندەیی ڕووداو."]},{heading:"٢. پلانی وەڵامدانەوەی تەنگانە (ERP)",body:"پلانی وەڵامدانەوەی تەنگانە (Emergency Response Plan) بەپێی ستانداردەکان:",points:["پلانی کاری تەنگانە دەبێت نووسراو بێت و لە کارگەدا بەردەست بێت؛ ئەو کارگانەی ١٠ کارمەند یان کەمتریان هەیە دەتوانن بە زارەکی ڕایبگەیەنن (OSHA 29 CFR 1910.38).","بەشە سەرەکییەکان: ئەرک، ڕێکار، ڕێگاکانی دەرچوون، پەیوەندی، سەرچاوەکان، مەشق و هەڵسەنگاندنی دوای ڕووداو.","خاڵەکانی کۆبوونەوە (Assembly Points): یەکێکی سەرەکی و یەکێکی یەدەگ، لە شوێنێکی سەلامەت و دوور لە بینا و ڕێگای ئۆتۆمبێلەکانی تەنگانە.","ڕێگاکانی دەرچوون: بە گشتی لانیکەم ٢ ڕێگا لە هەر نهۆمێک (NFPA 101، لەگەڵ هەندێک ئاوارتە).","زەنگی ئاگر (Alarm): دەبێت لە هەموو شوێنەکانی بینادا ببیسترێت یان ببینرێت (NFPA 72).","تیمی فریاکەوتنی سەرەتایی: لە هەر دەوامێکدا (Shift) کارمەندی ڕاهێنراو لەسەر فریاکەوتنی سەرەتایی و CPR هەبن.","مەشق (Drill): بە ڕێکوپێکی، و ئەنجامی هەر مەشقێک تۆمار بکرێت.","هەڵسەنگاندنی دوای ڕووداو (Post-Response Critique): لە زووترین کاتدا دوای هەر ڕووداوێک."]},{heading:"٣. هەماهەنگی لەگەڵ بەرگریی شارستانی (١١٥)",body:"کاتێک ڕووداو ڕوودەدات و تیمەکانی ١١٥ دەگەن، دەبێت ERT ئەم هەنگاوانە بنێت:",points:["١. یەکسەر پەیوەندی بە ١١٥ بکە، و بە ١٢٢ ئەگەر بریندار هەبوو.","٢. زانیارییە سەرەکییەکان بدە: شوێن، جۆری ڕووداو، ژمارەی بریندارەکان، ماددە مەترسیدارەکان و ڕێگای گەیشتن.","٣. نەخشەی کارگە (Site Map) لەبەردەم دەرگا ئامادە بکە، لەگەڵ شوێنەکانی مەترسی و شوێنەکانی بڕینی کارەبا و گاز.","٤. کەسی پەیوەندی (Liaison Officer): تەنها یەک کەس پەیوەندی لەگەڵ ١١٥ دەکات.","٥. پەڕەکانی SDS بۆ هەموو ماددە کیمیاییەکان ئامادە بکە.","٦. ناو و گوتەی شایەتەکان تۆمار بکە.","٧. گواستنەوەی فەرماندەیی: کاتێک ١١٥ دەگات، فەرماندەیی دەچێتە دەست فەرماندەی ١١٥ و ERT یارمەتی دەدات.","٨. بەڵگەنامە: وێنە، ڤیدیۆ و تۆماری ڕووداو (Incident Log) بۆ لێکۆڵینەوە و بیمە."]},{heading:"٤. کارکردن لەگەڵ تیمی ماددە مەترسیدارەکان (HazMat)",body:"بۆ ڕووداوە کیمیاییەکان، تیمی HazMat پێویستە:",points:["ئاستەکانی ڕاهێنانی HazMat (OSHA 1910.120 و NFPA 470، کە NFPA 472 ی تێدا کۆکراوەتەوە):","• ئاستی هۆشیاری (Awareness): ناسینی مەترسی، دوورکەوتنەوە و ئاگادارکردنەوە — بۆ هەموو کارمەندان.","• ئاستی کارپێکردن (Operations): پاراستنی خەڵک و دەوروبەر بە ڕێگا بەرگرییەکان (Defensive) لە دوورەوە.","• ئاستی تەکنیکی (Technician): ڕاگرتنی دزەکردن لە نزیکەوە (Offensive) بە PPE ی تایبەت.","• ئاستی پسپۆڕ (Specialist): زانیاریی قووڵ لەسەر ماددە دیاریکراوەکان و پشتگیریکردنی تەکنیکییەکان.","سێ ناوچە: ناوچەی گەرم (Hot Zone)، ناوچەی نیمچەگەرم (Warm Zone) و ناوچەی سارد (Cold Zone).","ئاستەکانی PPE ی HazMat: A، B، C، D (A بەرزترین پاراستنە).","پاککردنەوەی پیسبوون (Decontamination) لە ناوچەی نیمچەگەرمدا دەکرێت، پێش چوون بۆ ناوچەی سارد.","کارمەندانی ڕاهێنەنەکراو ناچنە ناوچەی گەرم؛ چاوەڕێی تیمەکانی ١١٥ بن.","پلانی کارگە دەبێت دیاری بکات کە تیمە تایبەتەکانی ماددە مەترسیدارەکان چۆن لە ڕێگەی ١١٥ ەوە داوا دەکرێن."]},{heading:"٥. وەڵامدانەوەی چەند دەزگایەک پێکەوە (Multi-Agency Response)",body:"ڕووداوە گەورەکان پێویستیان بە چەند دەزگایەک دەبێت:",points:["١١٥ بەرگریی شارستانی: کوژاندنەوەی ئاگر، ڕزگارکردن و ماددە مەترسیدارەکان.","١٢٢ ئەمبولانس: چارەسەری پزیشکی و گواستنەوەی بریندارەکان.","١٠٤ پۆلیس: گەمارۆدانی دەوروبەر، هاتوچۆ و لێکۆڵینەوەی یاسایی.","دەزگاکانی ئاسایش: لە کاتی گومانی تەقەمەنی یان تیرۆردا — لە ڕێگەی ١٠٤ ەوە ئاگادار دەکرێنەوە.","وەزارەتی تەندروستی: ئامادەکردنی نەخۆشخانە نزیکەکان.","فەرمانگەی کارەبا: بڕینی کارەبا لە دەوروبەر.","دەزگاکانی ئاو و گاز: بڕینی هێڵەکانی ئاو و گاز.","دەستەی ژینگە: ئەگەر ماددە کیمیاییەکان لە ژینگەدا بڵاو بوونەوە.","ناوەندی کارەکانی تەنگانە (EOC): بۆ ڕووداوە گەورەکان کە چەندین دەزگا تێیدا بەشدار دەبن."]},{heading:"٦. قۆناغەکانی وەڵامدانەوە (٥ قۆناغ)",body:"هەر ڕووداوێک بەم ٥ قۆناغەدا تێدەپەڕێت:",points:["١. ناسینەوە (Detection): هەستەوەر، زەنگی ئاگر یان شایەت.","٢. ئاگادارکردنەوە (Notification): پەیوەندیکردن بە ١١٥ ەوە، و ئاگادارکردنەوەی ERT و کەسی پەیوەندی.","٣. وەڵامدانەوە (Response): ERT کار دەکات تا تیمەکانی ١١٥ دەگەن.","٤. کەمکردنەوەی مەترسی (Mitigation): کوژاندنەوەی ئاگر، ڕزگارکردن و پاککردنەوەی پیسبوون.","٥. گەڕانەوە بۆ باری ئاسایی (Recovery): پاککردنەوە، شیکردنەوە و هەڵسەنگاندنی دوای ڕووداو.","دەبێت هەر قۆناغێک تۆمار بکرێت (Incident Action Plan — IAP).","کاتژمێری زێڕین (Golden Hour): چارەسەری خێرا دوای برینداربوونی سەخت دەرفەتی مانەوە لە ژیاندا زیاد دەکات — بۆیە پەیوەندیکردنی خێرا بە ١٢٢ ەوە گرنگە."]},{heading:"٧. مەشق و ڕاهێنان (Drills & Training)",body:"مەشق بنەمای ئامادەباشییە (خشتەی پێشنیارکراو):",points:["مەشقی سەر مێز (Tabletop Exercise): هەر ٣ مانگ جارێک — سیناریۆ لەسەر مێز.","مەشقی کرداری (Functional Drill): هەر ٦ مانگ جارێک — تەنها تیمی ERT، نەک هەموو بیناکە.","مەشقی تەواو (Full-Scale Drill): ساڵی جارێک — هەموو کارگەکە لەگەڵ ١١٥.","هەڵسەنگاندن: ڕاپۆرتی دوای مەشق (After-Action Report) لە زووترین کاتدا.","ڕاهێنانی ERT: بە بەردەوامی و بەپێی ئەرکەکان، لانیکەم ساڵی جارێک.","ستانداردەکانی شارەزایی: NFPA 1081 (Facility Fire Brigade Member)، OSHA 1910 Subpart L، و ICS-100/200.","مەشقی هاوبەش لەگەڵ ١١٥: ساڵی جارێک بۆ هەماهەنگی."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"مەشقی وەڵامدانەوەی ERT",description:"مەشقی تەواو لە کارگەیەکی نەوتدا"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"پەیکەری فەرماندەیی ڕووداو (ICS)",description:"پەیکەری فەرماندەیی ڕووداو (ICS)"}],quiz:[{question:"قەبارەی تیمی وەڵامدانەوەی تەنگانە (ERT) لە کارگەدا چۆن دیاری دەکرێت؟",options:[{text:"بە ڕێژەیەکی جێگیر: ١ بۆ هەر ١٠٠ کارمەند",correct:!1},{text:"بەپێی هەڵسەنگاندنی مەترسییەکانی کارگە و ئەرکەکانی تیم",correct:!0},{text:"بە ڕێژەیەکی جێگیر: ١ بۆ هەر ٢٠٠ کارمەند",correct:!1},{text:"بە ڕێژەیەکی جێگیر: ١ بۆ هەر ٢٥ کارمەند",correct:!1}],explanation:"NFPA 600 ڕێژەیەکی جێگیری ئەندامان بەرامبەر ژمارەی کارمەندان دیاری ناکات؛ هەر کارگەیەک بەپێی مەترسی و ئەرکەکانی خۆی قەبارەی تیم دیاری دەکات."},{question:"کاتژمێری زێڕین (Golden Hour) واتای چییە؟",options:[{text:"کاتژمێرێکی تایبەتی کار",correct:!1},{text:"کاتی سەرەتا دوای برینداربوونی سەخت، کە چارەسەری خێرا تێیدا زۆر گرنگە",correct:!0},{text:"کاتی نیوەڕۆ",correct:!1},{text:"گەرمای ڕۆژ",correct:!1}],explanation:"Golden Hour ئەو ماوەیەیە دوای برینداربوونی سەخت کە گەیاندنی خێرای بریندار بۆ چارەسەر دەرفەتی مانەوە لە ژیاندا زیاد دەکات؛ بۆیە یەکسەر پەیوەندی بە ١٢٢ بکە."},{question:"لە سیستەمی ICS دا، کەسی پەیوەندی (Liaison Officer) چی دەکات؟",options:[{text:"ئاگر دەکوژێنێتەوە",correct:!1},{text:"پەیوەندی لەگەڵ دەزگا دەرەکییەکان دەکات",correct:!0},{text:"CPR دەکات",correct:!1},{text:"دەرگاکە دادەخات",correct:!1}],explanation:"کەسی پەیوەندی پەیوەندی لەگەڵ ١١٥، پۆلیس (١٠٤)، ئەمبولانس (١٢٢) و دەزگاکانی تر دەکات."},{question:"ئاستی Operations ی HazMat چی دەکات؟",options:[{text:"تەنها ئاگادارکردنەوە",correct:!1},{text:"بەرگری (Defensive) — ڕێگرتن لە بڵاوبوونەوە لە دوورەوە",correct:!0},{text:"Offensive — ڕاگرتنی دزەکردن لە نزیکەوە",correct:!1},{text:"پسپۆڕی (Specialist)",correct:!1}],explanation:"ئاستی Operations بەرگرییە (Defensive): ڕێگرتن لە بڵاوبوونەوەی ماددەکە لە دوورەوە، نەک کارکردن لە نزیکەوە (Offensive)."},{question:"ناوچەی گەرم (Hot Zone) لە HazMat دا چییە؟",options:[{text:"شوێنێکی سارد و سەلامەت",correct:!1},{text:"ناوچەیەکی بە تەواوی پاک",correct:!1},{text:"مەترسیدارترین ناوچە — تەنها تەکنیکییەکانی HazMat بە PPE ی گونجاو",correct:!0},{text:"ناوچەی کۆبوونەوە",correct:!1}],explanation:"ناوچەی گەرم شوێنی ماددە مەترسیدارەکەیە؛ تەنها تەکنیکییەکانی HazMat بە PPE ی ئاستی A یان B دەچنە ناوی."},{question:"کاتێک تیمەکانی ١١٥ دەگەنە شوێنی ڕووداوەکە، فەرماندەیی دەچێتە دەست کێ؟",options:[{text:"ERT بەردەوام دەبێت",correct:!1},{text:"فەرماندەی ١١٥",correct:!0},{text:"بەڕێوەبەری کارگە",correct:!1},{text:"پۆلیس",correct:!1}],explanation:"گواستنەوەی فەرماندەیی (ICS Transfer): کاتێک ١١٥ دەگات، فەرماندەیی دەچێتە دەست فەرماندەی ١١٥ و ERT یارمەتی دەدات."}]},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"پۆلێنکردنی ئاگر لە کارگەکاندا",subtitle:"Industrial Fire Classes — NFPA 30/484/654",summary:"پۆلێنکردنی تایبەت بۆ کارگەکان: شلەمەنی، گاز، کانزا و تۆزی ئاگرگر",blocks:[{body:"ئەم مۆدیوڵە سیستەمی NFPA بەکاردەهێنێت: A کەرەستەی ڕەق، B شلەمەنی و گازە ئاگرگرەکان، C ئامێرە کارەباییەکان، D کانزاکان، K ڕۆنی چێشتخانە. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. ستانداردە تایبەتەکان لە کارگەکاندا: شلەمەنییە ئاگرگرەکان (NFPA 30)، کانزا ئاگرگرەکان (NFPA 484) و تۆزی ئاگرگر (NFPA 654). لە چاپی ٢٠٢٥ ەوە، NFPA 484 و NFPA 654 لە ستانداردی NFPA 660 دا کۆکراونەتەوە."},{heading:"١. پۆلی A — کەرەستە ڕەقە ئاگرگرەکان لە کارگەدا",body:"کەرەستە ڕەقە بڵاوەکان لە کارگەکاندا:",points:["سووتەمەنی: کاغەز، کارتۆن، قوماش، دار، لاستیک، پلاستیک و پالێت (Pallets).","ئەم ماددانە خەڵووز و ئاگری شاراوە بەجێدەهێڵن؛ دوای کوژاندنەوە شوێنەکە بە ئاو سارد بکەرەوە و چاودێری بکە.","لە کارگەکاندا: کۆگاکانی کاغەز و کارتۆن و پالێتە دارینەکان ئاگر بە خێرایی بڵاو دەکەنەوە.","ئاگرکوژێنەرەوە: ئاو، کەف، تۆزی ABC.","پالێتە بەتاڵە کەڵەکەکراوەکان مەترسییەکی گەورەن: بە بەرزی کەڵەکەیان مەکە، و لە دەرەوە یان لە شوێنێکی خاوەن سپرینکلەر هەڵیانبگرە.","ستاندارد: NFPA 13 (سیستەمەکانی سپرینکلەر)، کە پاراستنی کۆگاکانیشی تێدایە.","نموونە لە کارگەکاندا: کۆگا و هێڵەکانی پاکەتکردن (Packaging Lines)."]},{heading:"٢. پۆلی B — شلەمەنییە ئاگرگرەکان لە کارگەدا",body:"یەکێک لە مەترسیدارترین پۆلەکان لە کارگەکاندا:",points:["سووتەمەنی: بەنزین، نەوت، دیزڵ، ئەسیتۆن (Acetone)، تۆلوین (Toluene)، زایلین (Xylene).","خاڵی هەڵگیرسان (Flash Point): بەنزین نزیکەی -٤٣°C، ئەسیتۆن -٢٠°C، دیزڵ ٥٢°C یان زیاتر.","سنوورەکانی تەقینەوە (LEL/UEL): کەمترین و زۆرترین چڕیی هەڵم لە هەوادا کە دەتوانێت ئاگر بگرێت:","• بەنزین: ١٫٤-٧٫٦٪","• ئەسیتۆن: ٢٫٥-١٢٫٨٪","• میتانۆڵ (Methanol): ٦-٣٦٪","ئاگرکوژێنەرەوە: کەف (AFFF یان کەفی بێ فلۆر)، CO₂، تۆزی ABC. بۆ ئەسیتۆن، میتانۆڵ، ئەلکهول و شلە جەمسەرییەکانی تر (polar solvents): CO₂، تۆزی وشک یان کەفی بەرگەگری ئەلکهول (AR foam)؛ کەفی ئاسایی لەسەریان تێکدەچێت.","فیچقەی ئاو بەسەر شلەمەنییەکەدا مەکە — ئاگرەکە بڵاو دەکاتەوە. BLEVE (Boiling Liquid Expanding Vapor Explosion) کاتێک ڕوودەدات کە تانکێکی پەستاندار بە ئاگر گەرم دەبێت.","پۆلەکانی شلەمەنی بەپێی NFPA 30 (Flash Point = خاڵی هەڵگیرسان، Boiling Point = خاڵی کوڵان):","• Class I (Flammable): خاڵی هەڵگیرسان کەمتر لە ٣٧٫٨°C — IA (هەڵگیرسان < ٢٢٫٨°C و کوڵان < ٣٧٫٨°C)، IB (هەڵگیرسان < ٢٢٫٨°C و کوڵان ٣٧٫٨°C یان زیاتر)، IC (هەڵگیرسان ٢٢٫٨ تا < ٣٧٫٨°C).","• Class II (Combustible): خاڵی هەڵگیرسان ٣٧٫٨ تا < ٦٠°C.","• Class III (Combustible): IIIA لە ٦٠ تا < ٩٣°C، و IIIB ٩٣°C یان زیاتر.","دیوارەکانی ڕاگرتن (Diking): بەپێی NFPA 30، قەبارەی شوێنی ڕاگرتن دەبێت کەمتر نەبێت لەو شلەمەنییەی کە دەتوانێت لە گەورەترین تانکی پڕەوە بڕژێت (١٠٠٪)؛ ڕێژەی ١١٠٪ لە هەندێک یاسا و ڕێنماییی تردا داوا دەکرێت (بۆ ئاوی بارانیش).","چڕیی هەڵم (Vapor Density): هەڵمی بەنزین لە هەوا قورسترە (نزیکەی ٣-٤ جار) و لە شوێنە نزمەکاندا کۆ دەبێتەوە."]},{heading:"٣. گازە ئاگرگرەکان — NFPA: پۆلی B، EN 2: پۆلی C",body:"گازەکانی کارگە: ئەسیتیلین، پرۆپان، هایدرۆجین:",points:["سەرچاوە: ئەسیتیلین (Acetylene) بۆ لەحیمکردن، پرۆپان (Propane) بۆ هەندێک فۆرکلیفت، هایدرۆجین (Hydrogen) لە بارگاویکردنی باترییە ئەسیدییەکان (Lead-acid).","ئەم گازانە لە پلەی گەرمیی ئاساییدا گازن و بە ئاسانی ئاگر دەگرن. سنوورەکانی تەقینەوە لە هەوادا: هایدرۆجین ٤-٧٥٪، پرۆپان ٢٫١-٩٫٥٪، ئەسیتیلین لە ٢٫٥٪ و زیاتر. (-٢٥٣°C خاڵی کوڵانی هایدرۆجینە، نەک خاڵی هەڵگیرسان.)","گەرمیی بڵێسەی ئۆکسی-ئەسیتیلین (Oxy-Acetylene) لە ٣٠٠٠°C زیاترە.","ئەسیتیلین لەگەڵ مس (Copper) ماددەیەکی تەقەمەنی دروست دەکات (Copper Acetylide)؛ بۆری و ئامێری مسیی نەگونجاو بەکارمەهێنە.","کوژاندنەوە: یەکەم، ئەگەر بێ مەترسی بوو، ڤاڵڤی گاز دابخە. ئاگری گاز مەکوژێنەرەوە ئەگەر نەتتوانی هاتنی گاز ڕابگریت — گازی دزەکردوو دەتوانێت تەقینەوە دروست بکات.","تیمەکانی ١١٥ پرژاندنی ئاو (Water Spray) لە دوورەوە بۆ ساردکردنەوەی سیلیندەر و تانکەکان بەکاردەهێنن، نەک بۆ کوژاندنەوەی بڵێسەی گاز.","ئامێرەکانی دۆزینەوەی گاز (Gas Detectors) لە کۆگاکانی گازدا: زەنگی ئاگادارکردنەوە دەبێت زۆر پێش گەیشتن بە LEL لێبدات (بە گشتی لە ١٠-٢٠٪ ی LEL).","لە کارگەکاندا: شوێنەکانی لەحیمکردن، شوێنەکانی بارگاویکردنی فۆرکلیفت و ژوورەکانی باتری."]},{heading:"٤. پۆلی D — کانزا ئاگرگرەکان (NFPA 484)",body:"کانزا ئاگرگرەکان — یەکێک لە مەترسیدارترین جۆرەکان:",points:["سووتەمەنی: مەگنیسیۆم، تیتانیۆم، تۆزی ئەلەمنیۆم، سۆدیۆم و لیتیۆمی کانزایی (Lithium Metal).","ئەم کانزایانە بە گەرمییەکی زۆر بەرز دەسووتێن و ڕووناکییەکی زۆر توند دەدەن؛ ڕاستەوخۆ سەیری بڵێسەکە مەکە.","ئاو قەدەغەیە! Mg + H₂O → MgO + H₂ (هایدرۆجین دروست دەبێت و دەتوانێت بتەقێتەوە).","CO₂ قەدەغەیە! 2Mg + CO₂ → 2MgO + C (مەگنیسیۆم لە ناو CO₂ یشدا دەسووتێت).","تەنها ئاگرکوژێنەرەوەکانی پۆلی D، و تەنها ئەوەی ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت: ماددەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە (بۆ نموونە تۆز لەسەر بنەمای کلۆریدی سۆدیۆم (NaCl) یان گرافیت؛ تۆزی مس بۆ لیتیۆم). هەرگیز ئاو، تۆزی ئاسایی یان کەف بەکار مەهێنە. لمی وشک تەنها ئەگەر پلانی ئاگری شوێنەکە یان SDS ی کانزاکە ناوی هێنابێت و تەواو وشک بێت.","نموونە لە کارگەکاندا: تواندنەوەی ئەلەمنیۆم، تاشینی مەگنیسیۆم و باترییەکانی لیتیۆمی کانزایی.","NFPA 484: هەڵگرتن، مامەڵەکردن و پاراستنی کانزا ئاگرگرەکان (ئێستا بەشێکە لە NFPA 660).","تۆزی ئەلەمنیۆم: مەترسیی تەقینەوەی تۆزیشی هەیە (NFPA 654 / 660).","وەڵامدانەوە: یەکسەر پەیوەندی بە ١١٥ بکە و تەنها ئاگرکوژێنەرەوەی پۆلی D بەکاربهێنە کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت. باترییەکانی لیتیۆم-ئایۆن (Li-ion) لیتیۆمی کانزاییان تێدا نییە و بە ئاو سارد دەکرێنەوە."]},{heading:"٥. تۆزی ئاگرگر — تەقینەوەی تۆز (NFPA 654)",body:"مەترسییەکی کوشندە لە کارگەکاندا:",points:["پێنجگۆشەی تۆز (Dust Pentagon): سووتەمەنی (تۆز) + ئۆکسجین + گەرمی + بڵاوبوونەوە لە هەوادا + شوێنی داخراو.","سەرچاوە: ئارد، شەکر، دار، خەڵووز، تۆزی کانزاکان و پلاستیک.","کەمترین پلەی گەرمیی هەڵگیرسان (MIT) بەپێی جۆری تۆزەکە دەگۆڕێت؛ سەیری SDS یان ئەنجامەکانی تاقیکردنەوەی تۆز بکە.","کەمترین چڕیی تەقینەوە (MEC) یش بەپێی جۆری تۆزەکە دەگۆڕێت؛ تۆزی بڵاوبووە لە هەوادا هەمیشە مەترسیدارە.","تەقینەوەی یەکەم (Primary): لە ناو ئامێرێکدا (وەک فلتەر یان ئاش).","تەقینەوەی دووەم (Secondary): تەقینەوەی یەکەم تۆزی سەر زەوی و ڕەف و بۆرییەکان بەرز دەکاتەوە، و تەقینەوەیەکی گەورەتر و کوشندەتر ڕوودەدات.","کەمکردنەوەی مەترسی: سیستەمەکانی کۆکردنەوەی تۆز، دەرگاکانی بەتاڵکردنەوەی تەقینەوە (Explosion Vents) و سیستەمەکانی کوژاندنەوە.","پاکوخاوێنی: چینێکی تۆز بە ئەستووریی ٠٫٨ ملم (1/32 inch) لەسەر زیاتر لە ٥٪ ی ڕووبەری زەوی دەتوانێت مەترسی دروست بکات (NFPA 654 / OSHA).","نموونە: لە ساڵی ٢٠٠٨ لە کارگەی شەکری Imperial Sugar (ئەمریکا)، تەقینەوەی تۆزی شەکر ١٤ کرێکاری کوشت (CSB).","ستاندارد: NFPA 654 (ئێستا NFPA 660) و OSHA 29 CFR 1910.272 (بۆ کۆگاکانی دانەوێڵە)."]},{heading:"٦. قۆناغەکانی گەشەکردنی ئاگر لە کارگەدا",body:"٤ قۆناغی ستاندارد — لە کارگەکاندا ئاگر دەتوانێت خێراتر بێت:",points:["سەرەتا (Incipient): ئاگرێکی بچووک — کەسێکی ڕاهێنراو دەتوانێت بە ئاگرکوژێنەرەوەی دەستیی گونجاو بیکوژێنێتەوە، دوای دانی ئاگادارکردنەوە و پەیوەندیکردن بە ١١٥ەوە، و ڕێگای دەرچوون لە پشتیەوە بێت؛ ئەگەر یەکسەر نەکوژایەوە، دەربچۆ.","گەشەکردن (Growth): ئاگر و دووکەڵ بە خێرایی زیاد دەبن و سپرینکلەرەکان کار دەکەن — دەربچۆ و پەیوەندی بە ١١٥ بکە.","گەشەی تەواو (Fully Developed): دوای Flashover — تەنها تیمەکانی ١١٥.","کەمبوونەوە (Decay): سووتەمەنی کەم دەبێتەوە، بەڵام مەترسیی Backdraft و ڕووخان دەمێنێت.","لە کارگەکاندا، کۆگا بەرزەکان، پالێت و شلەمەنییەکان دەتوانن ئاگر خێراتر لە ماڵەکان بگەیەننە قۆناغی تەواو.","تانکی گاز و شلەمەنیی پەستاندار ئەگەر بە ئاگر گەرم ببن دەتوانن بە BLEVE بتەقنەوە — دەوروبەر بە خێرایی چۆڵ بکە.","پلانی کارگە دەبێت ڕێگای گەیشتنی تیمەکانی ١١٥ و شوێنەکانی ئاوی ئاگرکوژاندنەوە (Hydrants) ئامادە و کراوە بهێڵێتەوە.","چاودێری ئاگر دوای کاری گەرم (Hot Work): لە کاتی کاردا و لانیکەم ١ کاتژمێر دوای تەواوبوون، پاشان چاودێری تا ٣ کاتژمێری تر بەپێی بڕیاری بەرپرسی مۆڵەتەکە (NFPA 51B)."]},{heading:"٧. باری ئاگر (Fire Load) و هەڵسەنگاندنی مەترسی",body:"پشکنینی مەترسی لە کارگەدا:",points:["باری ئاگر (Fire Load Density — MJ/m²): بڕی ئەو وزەیەی کە ماددە ئاگرگرەکان لە هەر مەترێکی چوارگۆشەدا دەتوانن بیدەن. تێکڕاکانی EN 1991-1-2 (Eurocode 1):","• خانوو (Dwelling): نزیکەی ٧٨٠ MJ/m²","• نووسینگە (Office): نزیکەی ٤٢٠ MJ/m²","• کتێبخانە (Library): نزیکەی ١٥٠٠ MJ/m²","• کۆگا و کارگە: بەپێی ماددە هەڵگیراوەکان هەژمار دەکرێت و زۆر جار لەمانە بەرزترە.","هەڵسەنگاندنی مەترسی (Risk Assessment): مەترسی = ئەگەری ڕوودان (Likelihood) × قورسیی ئەنجام (Severity).","• کەم (Low): بە ڕێکارە ئاساییەکان کۆنترۆڵ دەکرێت.","• مامناوەند (Medium): پێویستی بە کۆنترۆڵی زیادە و چاودێری هەیە.","• بەرز (High): پێویستی بە کاری خێرا هەیە پێش بەردەوامبوونی کار.","• زۆر بەرز (Extreme): کار دەوەستێت تا مەترسی کەم دەبێتەوە.","بەرگریی دیوار و بانەکان دژی ئاگر (Fire Resistance Rating) بەپێی جۆر و بەکارهێنانی بینا لە کۆدەکانی بیناسازییەوە دیاری دەکرێت (وەک NFPA 101 و NFPA 5000).","هەڵسەنگاندنی مەترسییەکانی کارگە (وەک HVA) لانیکەم ساڵی جارێک و دوای هەر گۆڕانکارییەکی گەورە نوێ بکەرەوە."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"تەقینەوەی تۆز",description:"نمایشی تەقینەوەی تۆز"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"خشتەی پۆلەکانی ئاگر",description:"پۆلێنکردنی ئاگر لە کارگەکاندا"}],quiz:[{question:"بۆ ئاگری پۆلی D، کام ئاگرکوژێنەرەوە گونجاوە؟",options:[{text:"تۆزی ABC",correct:!1},{text:"ئاو",correct:!1},{text:"ئاگرکوژێنەرەوەی پۆلی D کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت",correct:!0},{text:"CO₂",correct:!1}],explanation:"تەنها ئاگرکوژێنەرەوەی پۆلی D یان ماددەیەک کە ناوی ئەو کانزایەی دەسووتێت لەسەر لەیبڵەکەی هاتبێت گونجاوە؛ ماددەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە. ئاو، CO₂ و تۆزی ABC بەکارمەهێنە."},{question:"BLEVE واتای چییە؟",options:[{text:"زەنگی ئاگر",correct:!1},{text:"Boiling Liquid Expanding Vapor Explosion",correct:!0},{text:"سیستەمی سپرینکلەر",correct:!1},{text:"پۆلی گاز",correct:!1}],explanation:"BLEVE تەقینەوەی تانکێکی پەستاندارە کە شلەمەنیی تێدایە، کاتێک بە ئاگر گەرم دەبێت و هەڵم بە خێرایی فراوان دەبێت."},{question:"پێنجگۆشەی تۆز (Dust Pentagon) چەند توخمی هەیە؟",options:[{text:"٣",correct:!1},{text:"٤",correct:!1},{text:"٥",correct:!0},{text:"٦",correct:!1}],explanation:"پێنج توخم: سووتەمەنی + ئۆکسجین + گەرمی + بڵاوبوونەوە + شوێنی داخراو."},{question:"ئەسیتیلین لەگەڵ مس (Copper) چی دروست دەکات؟",options:[{text:"هیچ ڕوونادات",correct:!1},{text:"Copper Acetylide — ماددەیەکی تەقەمەنی",correct:!0},{text:"پاککردنەوە",correct:!1},{text:"گەرمییەکی کەم",correct:!1}],explanation:"ئەسیتیلین لەگەڵ مس ماددەیەکی تەقەمەنیی هەستیار (Copper Acetylide) دروست دەکات کە بە لێدان یان گەرمی دەتەقێتەوە."},{question:"تۆزی ئەلەمنیۆم (Aluminum Powder) چ مەترسییەکی هەیە؟",options:[{text:"تەنها پۆلی A",correct:!1},{text:"پۆلی D و تەقینەوەی تۆز",correct:!0},{text:"تەنها گاز",correct:!1},{text:"هیچ مەترسییەکی نییە",correct:!1}],explanation:"تۆزی ئەلەمنیۆم هەم کانزای ئاگرگرە (پۆلی D) و هەم تۆزی ئاگرگرە (NFPA 484 / 654، ئێستا NFPA 660)."},{question:"بەپێی EN 1991-1-2، تێکڕای باری ئاگر لە خانووەکاندا (Dwelling) نزیکەی چەندە؟",options:[{text:"١٠٠ MJ/m²",correct:!1},{text:"٢٣٠ MJ/m²",correct:!1},{text:"٤٢٠ MJ/m²",correct:!1},{text:"٧٨٠ MJ/m²",correct:!0}],explanation:"تێکڕای باری ئاگر لە خانووەکاندا نزیکەی ٧٨٠ MJ/m² ە، و لە نووسینگەکاندا نزیکەی ٤٢٠ MJ/m² (EN 1991-1-2، خشتەی E.4)."}]},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"سیستەمەکانی کوژاندنەوەی ئاگر لە کارگەکاندا",subtitle:"Portable Extinguishers + Fixed Systems (Sprinkler/Foam/CO₂)",summary:"ئاگرکوژێنەرەوە دەستییەکان و سیستەمە جێگیرەکانی کوژاندنەوەی ئاگر لە کارگەکاندا",blocks:[{body:"کارگە پێویستی بە دوو ئاستی کوژاندنەوەی ئاگر هەیە: ١) ئاگرکوژێنەرەوە دەستییەکان (Portable Extinguishers) بۆ ئاگری بچووک لە قۆناغی سەرەتاییدا، ٢) سیستەمە جێگیرەکان (Fixed Suppression Systems) بۆ پاراستنی بەردەوام. بەپێی جۆری مەترسی: سپرینکلەر (NFPA 13)، کەف (NFPA 11 / 16)، CO₂ (NFPA 12)، تۆزی وشک (NFPA 17) و Clean Agent (NFPA 2001). ئەم مۆدیوڵە ئەم سیستەمانە و خشتەی پشکنین ڕوون دەکاتەوە."},{heading:"١. ئاگرکوژێنەرەوە دەستییەکان — هەڵبژاردن لە کارگەدا",body:"٧ جۆری سەرەکی و خشتەی هەڵبژاردن:",points:["تۆزی ABC (Multi-purpose): بڵاوترین جۆر بۆ ڕاڕەو و شوێنە گشتییەکان — A، B، C (نەک D و K).","CO₂: بۆ تابلۆکانی کارەبا و ژوورەکانی سێرڤەر — B، C.","کەف (AFFF / Foam): بۆ کۆگاکانی شلەمەنی و شوێنەکانی دیواری ڕاگرتن — A، B.","Wet Chemical (کیمیایی شل): بۆ چێشتخانە و کافتریای کارگە — K.","Clean Agent: بۆ ژوورەکانی سێرڤەر و کۆنترۆڵ.","پۆلی D (ماددەیەک کە ناوی ئەو کانزایەی لەوێ بەکاردێت لەسەر لەیبڵەکەی هاتبێت): بۆ تاشینی کانزاکان و تواندنەوەی ئەلەمنیۆم.","Water Mist (ئاوی وردی بێ کانزا): بۆ A، و هەندێک مۆدێل بۆ C — بەپێی لیستکردنی ئامێرەکە.","ئاستەکانی مەترسی بەپێی NFPA 10 (کەمترین هەڵسەنگاندنی ئاگرکوژێنەرەوەی پۆلی A):","• مەترسیی کەم (Light Hazard — نووسینگە): 2-A","• مەترسیی ئاسایی (Ordinary Hazard — کارگەی ئاسایی): 2-A","• مەترسیی زیاد (Extra Hazard — کارگەی خاوەن سووتەمەنیی زۆر): 4-A","دووریی گەیشتن (Travel Distance) تا ئاگرکوژێنەرەوە:","• پۆلی A: تا ٢٣ مەتر (٧٥ پێ) لە هەموو ئاستەکاندا.","• پۆلی B: ٩ یان ١٥ مەتر (٣٠ / ٥٠ پێ) بەپێی هەڵسەنگاندنی ئاگرکوژێنەرەوەکە و ئاستی مەترسی."]},{heading:"٢. سیستەمەکانی سپرینکلەر — NFPA 13",body:"گرنگترین سیستەمی جێگیر لە زۆربەی کارگەکاندا:",points:["٤ جۆری سیستەمی سپرینکلەر:","• بۆریی تەڕ (Wet Pipe): بۆرییەکان هەمیشە پڕن لە ئاو — خێراترین وەڵامدانەوە و بڵاوترین جۆر.","• بۆریی وشک (Dry Pipe): بۆرییەکان پڕن لە هەوا یان نایترۆجینی پەستاندار — بۆ ئەو شوێنانەی پلەی گەرمی تێیاندا لە ٤°C دادەبەزێت.","• پێش-کارکردن (Pre-action): ڤاڵڤەکە تەنها دوای ناسینەوەی ئاگر بە دیتێکتەرەکان دەکرێتەوە، پاشان سەری سپرینکلەرەکە بە گەرمی دەکرێتەوە — بۆ شوێنی ئامێرە هەستیارەکان.","• Deluge: سەرەکان کراوەن، و هەموویان پێکەوە ئاو دەپرژێنن — بۆ شوێنە بەرز مەترسییەکان.","پلەی گەرمیی کرانەوە (Activation Temperature) و ڕەنگی گڵۆپە شووشەییەکە:","• ٥٧°C (پرتەقاڵی): پلەی ئاسایی (Ordinary) — ئەو شوێنانەی پلەی گەرمییان نزمە.","• ٦٨°C (سوور): پلەی ئاسایی (Ordinary) — بڵاوترین لە نووسینگە و کارگەکاندا.","• ٧٩°C (زەرد) و ٩٣°C (سەوز): پلەی مامناوەند (Intermediate) — شوێنە گەرمترەکان.","• ١٤١°C (شین): پلەی بەرز (High) — ژوورەکانی بۆیلەر و نزیک ئامێرە گەرمەکان.","ڕووبەری پاراستن بۆ هەر سەرێکی ئاسایی (Standard Spray): تا نزیکەی ٢١ m² (Light)، ١٢ m² (Ordinary) و ٩ m² (Extra Hazard).","چڕیی ئاو (Density): 0.10-0.40 gpm/ft² (نزیکەی ٤-١٦ mm/min) بەپێی ئاستی مەترسی.","NFPA 25: پشکنین و تاقیکردنەوە بە خشتەی هەفتانە، مانگانە، ساڵانە و ٥ ساڵانە.","سپرینکلەرەکان تەنها لە شوێنی ئاگرەکەدا دەکرێنەوە؛ هەموو سەرەکان پێکەوە ناکرێنەوە (جگە لە سیستەمی Deluge)."]},{heading:"٣. سیستەمەکانی کەف — NFPA 11 / 16",body:"بۆ کۆگا گەورەکانی شلەمەنی:",points:["٣ جۆری کەف بەپێی ڕێژەی فراوانبوون (Expansion):","• کەم (Low-Expansion، تا 20:1): ئاگری تانکەکان و ڕژانی شلەمەنی.","• مامناوەند (Medium-Expansion، 20:1 تا 200:1): شوێنەکانی دیواری ڕاگرتن.","• بەرز (High-Expansion، 200:1 تا 1000:1): هەنگارەکانی فڕۆکە و شوێنە گەورە داخراوەکان.","جۆرەکانی ماددەی کەف (Concentrate):","• AFFF: بۆ هایدرۆکاربۆنەکان (بەنزین، دیزڵ).","• AR-AFFF (Alcohol-Resistant): بۆ سۆڵڤێنتە پۆلارەکان (ئەلکهول، ئەسیتۆن).","• Fluoroprotein: بۆ تانکەکانی هەڵگرتن.","• کەفی بێ فلۆر (Fluorine-Free Foam — F3): جێگرەوەی کەفەکانی PFAS.","ڕێژەی بەکارهێنان (Application Rate):","• ڕژانی هایدرۆکاربۆنەکان: لانیکەم نزیکەی ٤٫١ L/min/m² (0.10 gpm/ft²).","• سۆڵڤێنتە پۆلارەکان: بەپێی لیستکردنی بەرهەمهێنەر، بە گشتی بەرزتر.","مەترسیی PFAS: AFFF ماددەی فلۆرینی (PFAS) ی تێدایە کە لە لەش و ژینگەدا کۆ دەبنەوە؛ زۆر وڵات بەرەو کەفی بێ فلۆر (F3) دەچن.","لە کارگەکاندا: کۆمەڵگاکانی تانک، شوێنەکانی بارکردنی تانکەر و پاڵاوگەکان."]},{heading:"٤. سیستەمەکانی CO₂ و Clean Agent — NFPA 12 / 2001",body:"بۆ ژوورەکانی ئامێر و پڕکردنەوەی تەواو (Total Flooding):",points:["پڕکردنەوەی تەواو بە CO₂:","• چڕیی دیزاین: لانیکەم ٣٤٪ (NFPA 12)، و بۆ هەندێک ماددە زیاتر.","• مەترسی: چڕیی کوژاندنەوە بۆ مرۆڤ کوشندەیە — نابێت هیچ کەسێک لە ژوورەکەدا بمێنێتەوە.","• زەنگی پێش-بەردان و ماوەی چاوەڕوانی (Time Delay): دەبێت بەس بێت بۆ چۆڵکردنی ژوورەکە پێش بەردانی گازەکە (NFPA 12).","• بەکارهێنان: ژوورەکانی مۆلیدە، شوێنەکانی تاقیکردنەوەی بزوێنەر و ئامێرەکانی چاپ.","Clean Agent (FK-5-1-12 / HFC-227ea):","• NOAEL: لەو شوێنانەی کەسیان لێیە، چڕیی دیزاین لە ئاستی بێ زیان (NOAEL) تێناپەڕێت (NFPA 2001)؛ لەگەڵ ئەوەشدا ژوورەکە چۆڵ بکە.","• چڕیی دیزاین: بە گشتی نزیکەی ٤-٩٪ بەپێی جۆری ماددەکە.","• بەردان (Discharge): ماددە هالۆکاربۆنییەکان لە ماوەی ١٠ چرکەدا (NFPA 2001).","• بەکارهێنان: ژوورەکانی سێرڤەر، کۆنترۆڵ و سویچ.","• نرخەکەی زۆر لە سیستەمەکانی ئاو بەرزترە.","Halon 1301: بەرهەمهێنانی بەپێی پرۆتۆکۆڵی مۆنتریاڵ لە ١٩٩٤ ەوە لە وڵاتە پێشکەوتووەکاندا ڕاگیراوە، چونکە چینی ئۆزۆن تێکدەدات؛ سیستەمی نوێی پێ دانانرێت.","تاقیکردنەوەی هایدرۆستاتیکیی ئاگرکوژێنەرەوە دەستییەکان (NFPA 10): CO₂ هەر ٥ ساڵ جارێک، Clean Agent هەر ١٢ ساڵ جارێک؛ سیلیندەرەکانی سیستەمە جێگیرەکان بەپێی NFPA 12 / 2001 و یاساکانی سیلیندەر."]},{heading:"٥. سیستەمەکانی تۆزی وشک — NFPA 17",body:"بۆ مەترسییە تایبەتەکان:",points:["سیستەمە ئامادەکراوەکان (Pre-Engineered Systems):","• چێشتخانە بازرگانییەکان: ئێستا بە گشتی سیستەمەکانی Wet Chemical (NFPA 17A) بەکاردەهێنرێن، نەک تۆزی وشک.","• ژوورەکانی ڕەنگکردن (Spray Booths).","• پاراستنی ئامێر و ئۆتۆمبێلە قورسەکان.","• تانکەکانی نوقمکردن (Dip Tanks).","ماددەکان (Agents):","• بیکاربۆناتی سۆدیۆم (Sodium Bicarbonate): B، C.","• بیکاربۆناتی پۆتاسیۆم (Purple-K): B، C — لەسەر ئاگری پۆلی B لە بیکاربۆناتی سۆدیۆم بەهێزترە.","• فۆسفاتی ئەمۆنیۆم (Monoammonium Phosphate): A، B، C.","• کلۆریدی پۆتاسیۆم (Potassium Chloride): B، C.","کرانەوە (Activation): دیتێکتەری گەرمی یان دەسکێکی دەستی (Manual Pull).","دوای بەردان: تۆزەکە لە هەموو شوێنێک بڵاو دەبێتەوە و دەتوانێت زیان بە ئامێرە ئەلیکترۆنییەکان بگەیەنێت؛ پاککردنەوەی قورسە.","ڕووبەری پاراستنی هەر لوولەیەک (Nozzle) بەپێی لیستکردنی سیستەمەکە دیاری دەکرێت."]},{heading:"٦. ناسینەوەی ئاگر — NFPA 72",body:"سیستەمی ناسینەوە — یەکەم هێڵی ئاگادارکردنەوە:",points:["جۆرەکانی دیتێکتەر:","• دووکەڵ: فۆتۆئەلیکتریک (Photoelectric) بۆ ئاگری هێواش (Smoldering)، ئایۆنیزەیشن (Ionization) بۆ ئاگری بڵێسەدار (Flaming).","• گەرمی: پلەی جێگیر (Fixed Temperature، وەک ٥٧°C) یان بەرزبوونەوەی خێرا (Rate-of-Rise).","• بڵێسە (Flame): UV/IR — بڵێسە بە خێرایی دەناسنەوە.","• گاز: دیتێکتەرەکانی LEL و هەستەوەرەکانی CO.","• کێشانی نموونەی هەوا (Air-Sampling): بۆ ژوورەکانی سێرڤەر — هەستیارترین جۆر.","دووری و ڕووبەر:","• دووکەڵ: دووریی نێوان دیتێکتەرەکان نزیکەی ٩ مەتر (30 ft) لەسەر بنمیچی ڕێک (NFPA 72).","• گەرمی: بەپێی دووریی لیستکراوی دیتێکتەرەکە (Listed Spacing).","• بڵێسە: بەپێی گۆشەی بینین و دووریی لیستکراوی ئامێرەکە.","ئاگادارکردنەوە (Alarm Notification):","• دەنگ (Audible): بە گشتی لانیکەم ١٥ dB لە تێکڕای دەنگی شوێنەکە بەرزتر (NFPA 72).","• ڕووناکی (Strobe): بۆ شوێنە پڕ ژاوەژاوەکان و بۆ ئەو کەسانەی کەمیی بیستنیان هەیە.","• ئاگادارکردنەوەی دەنگی (Voice / Mass Notification): بۆ بینا و کارگە گەورەکان.","پشکنین و تاقیکردنەوە: بەپێی خشتەکانی NFPA 72 (زۆرێک لە ئامێرەکان ساڵی جارێک تاقی دەکرێنەوە)."]},{heading:"٧. خشتەی پشکنین و چاکسازی",body:"بەپێی ستانداردەکانی NFPA:",points:["ڕۆژانە / هەفتانە:","• پشکنینی بینراو (پەستانی گەیجەکان، زیان).","• پشکنینی ئەوەی کە هیچ شتێک نەکەوتبێتە بەردەم سپرینکلەرەکان.","• هەڵکردنی پەمپی ئاگر بەبێ کردنەوەی ئاو (No-flow Test): پەمپی دیزڵ هەموو هەفتەیەک، هی کارەبا بە گشتی هەموو مانگێک (NFPA 25).","مانگانە:","• پشکنینی بینراوی ئاگرکوژێنەرەوە دەستییەکان (NFPA 10).","• پشکنینی پانێڵی زەنگی ئاگر و نیشانەکانی هەڵە (Trouble).","• پشکنینی دوگمەکانی زەنگ (Manual Pull Stations) — دیار و نەگیراو بن.","ساڵانە:","• چاکسازیی ساڵانەی ئاگرکوژێنەرەوە دەستییەکان لەلایەن کەسی شارەزاوە (نەک تاقیکردنەوەی هایدرۆستاتیکی).","• پشکنینی سپرینکلەرەکان لەسەر زەوییەوە (NFPA 25).","• نموونەی ماددەی کەف بۆ تاقیکردنەوە.","• تاقیکردنەوەی دیتێکتەر و زەنگەکان (NFPA 72).","هەر چەند ساڵ جارێک:","• تاقیکردنەوەی هایدرۆستاتیکیی ئاگرکوژێنەرەوەکان (تاقیکردنەوەی پەستانی لەشیان، NFPA 10): هەر ٥ ساڵ بۆ ئاو، کەف، Wet Chemical، CO₂ و تۆزی وشکی ستێنلێس ستیل (stainless steel)؛ هەر ١٢ ساڵ بۆ تۆزی وشکی پەستانی هەڵگیراو (stored-pressure) کە لەشی لە پۆڵای ئاسایی (mild steel)، بڕنجی لەحیمکراو (brazed brass) یان ئەلەمنیۆمە، و بۆ Clean Agent. بە جیا، هەر ٦ ساڵ جارێک، ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو کە پێویستیان بە تاقیکردنەوەی ١٢ ساڵە هەیە، لەلایەن کەسی شارەزاوە بەتاڵ دەکرێنەوە و ناوەوەیان دەپشکنرێت. ڕێساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە.","• پشکنینی ناوەوەی بۆرییەکانی سپرینکلەر: هەر ٥ ساڵ جارێک (NFPA 25).","• گۆڕین یان تاقیکردنەوەی نموونەی سەرەکانی سپرینکلەر دوای ٥٠ ساڵ (سەرە ئاساییەکان — NFPA 25).","تۆمارکردن: هەموو پشکنین و تاقیکردنەوەکان بنووسە و تۆمارەکان بەپێی ستانداردەکان و داواکاریی دەزگا پەیوەندیدارەکان بپارێزە."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"کرانەوەی سپرینکلەر",description:"نمایشی سپرینکلەر"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"خشتەی سیستەمەکانی کوژاندنەوە",description:"سیستەمە جێگیرەکان"}],quiz:[{question:"بۆ زۆربەی کارگەکان، گرنگترین سیستەمی جێگیر کامەیە؟",options:[{text:"ئاگرکوژێنەرەوە دەستییەکان",correct:!1},{text:"سپرینکلەر (NFPA 13)",correct:!0},{text:"تەنها CO₂",correct:!1},{text:"هیچ کامیان",correct:!1}],explanation:"سپرینکلەرەکان خۆکارانە کار دەکەن و ئاگر لە قۆناغی سەرەتاییدا کۆنترۆڵ دەکەن، تەنانەت کاتێک کەس لە شوێنەکەدا نییە؛ ئاگرکوژێنەرەوە دەستییەکان تەنها بۆ ئاگری بچووکن."},{question:"سیستەمی بۆریی تەڕ (Wet Pipe) بۆ کام شوێن گونجاو نییە؟",options:[{text:"ژوورەکانی ئامێر (ICT)",correct:!1},{text:"نووسینگە",correct:!1},{text:"ئەو شوێنانەی پلەی گەرمی تێیاندا لە ٤°C دادەبەزێت",correct:!0},{text:"کۆگا",correct:!1}],explanation:"لە شوێنە ساردەکاندا ئاو لە ناو بۆرییەکاندا دەیبەستێت؛ سیستەمی بۆریی وشک (Dry Pipe) گونجاوە."},{question:"ئایا سیستەمی نوێ بە Halon 1301 دادەنرێت؟",options:[{text:"بەڵێ",correct:!1},{text:"نەخێر — بەرهەمهێنانی بەپێی پرۆتۆکۆڵی مۆنتریاڵ ڕاگیراوە",correct:!0},{text:"تەنها لە ژوورەکانی ICT",correct:!1},{text:"تەنها لە ژوورەکانی سێرڤەر",correct:!1}],explanation:"Halon 1301 چینی ئۆزۆن تێکدەدات؛ بەرهەمهێنانی لە وڵاتە پێشکەوتووەکاندا لە ١٩٩٤ ەوە ڕاگیراوە."},{question:"بۆچی دەبێت هەموو کەسێک پێش بەردانی سیستەمی CO₂ ی پڕکردنەوەی تەواو لە ژوورەکە بچێتە دەرەوە؟",options:[{text:"پێویست ناکات، CO₂ بێ زیانە",correct:!1},{text:"چونکە چڕیی کوژاندنەوە (٣٤٪ و زیاتر) بۆ مرۆڤ کوشندەیە",correct:!0},{text:"چونکە CO₂ ئاو دەپرژێنێت",correct:!1},{text:"چونکە CO₂ دەنگێکی بەرز دروست دەکات",correct:!1}],explanation:"چڕیی دیزاینی CO₂ لە سیستەمەکانی پڕکردنەوەی تەواودا لانیکەم ٣٤٪ ە (NFPA 12)، و ئەم چڕییە لە ماوەیەکی کورتدا مرۆڤ بێهۆش دەکات و دەیکوژێت؛ بۆیە زەنگی پێش-بەردان و ماوەی چاوەڕوانی هەن."},{question:"ڕووبەری پاراستنی هەر سەرێکی سپرینکلەر (Standard Spray) نزیکەی چەندە؟",options:[{text:"٢-٥ m²",correct:!1},{text:"١٢-٢١ m²",correct:!0},{text:"٥٠ m²",correct:!1},{text:"١٠٠ m²",correct:!1}],explanation:"بەپێی NFPA 13: نزیکەی ٢١ m² بۆ مەترسیی کەم و ١٢ m² بۆ مەترسیی ئاسایی؛ بۆ مەترسیی زیاد کەمترە (نزیکەی ٩ m²)."},{question:"تاقیکردنەوەی هەفتانەی پەمپی ئاگری دیزڵ چییە؟",options:[{text:"تەنها پشکنینی بینراو",correct:!1},{text:"هەڵکردنی پەمپەکە بەبێ کردنەوەی ئاو (Start / No-flow Test)",correct:!0},{text:"تاقیکردنەوەی هایدرۆستاتیکی",correct:!1},{text:"هیچ کامیان",correct:!1}],explanation:"NFPA 25: پەمپی دیزڵ هەموو هەفتەیەک و پەمپی کارەبا بە گشتی هەموو مانگێک بەبێ کردنەوەی ئاو هەڵدەکرێن و تاقی دەکرێنەوە."}]}],t={lessons:e};export{t as default,e as lessons};
